class Playground{
    constructor(){
        this.simulation = new Simulation();
        this.mousePos = Vector2.Zero();
        this.lastMousePos = Vector2.Zero();
        this.selectedShape = null;
        this.keys = new Set();
    }

    update(dt){
        let turn = 0;
        if(this.keys.has("q")){
            turn -= 1;
        }
        if(this.keys.has("w")){
            turn += 1;
        }

        if(turn !== 0){
            this.simulation.rotateBottle(turn * Math.min(dt, 0.033) * 2.35);
        }

        let frameDt = Math.min(dt, 0.033);
        for(let i=0; i<4; i++){
            this.simulation.update(frameDt * 1.85);
        }
    }

    draw(){
        this.simulation.draw();
    }

    drawFluid(targetCtx){
        this.simulation.drawBeer(targetCtx);
    }

    drawBeer(targetCtx){
        this.simulation.drawBeer(targetCtx);
    }

    drawFoam(targetCtx){
        this.simulation.drawFoam(targetCtx);
    }

    drawBeerDetails(targetCtx){
        this.simulation.drawBeerDetails(targetCtx);
    }

    drawFoamDetails(targetCtx){
        this.simulation.drawFoamDetails(targetCtx);
    }

    setPourAmount(value){
        this.simulation.setPourAmount(value);
    }

    onMouseMove(position){
        this.lastMousePos = this.mousePos.Cpy();
        this.mousePos = position;
        this.simulation.setBottleCenter(position);
    }

    onMouseDown(button){
    }

    onMouseUp(button){
    }

    onKeyDown(key){
        this.keys.add(key.toLowerCase());
    }

    onKeyUp(key){
        this.keys.delete(key.toLowerCase());
    }
}

