2	    constructor(cellSize){
3	        this.cellSize = cellSize;
4	        this.hashMap = new Map();
5	        this.hashMapSize = 100000;
6	        this.prime1 = 661401;
7	        this.prime2 = 752887;
8	        this.particles = [];
9	    }
10	
11	    initialize(particles){
12	        this.particles = particles;
13	    }
14	
15	    clearGrid(){
16	        this.hashMap.clear();
17	    }
18	
19	    getGridHashFromPos(pos){
20	        let x = parseInt(pos.x / this.cellSize);
21	        let y = parseInt(pos.y / this.cellSize);
22	
23	        return this.cellIndexToHash(x,y);
24	    }
25	
26	    cellIndexToHash(x,y){
27	        let hash = (x * this.prime1 ^ y * this.prime2) % this.hashMapSize;
28	        return hash;
29	    }
30	
31	    getNeighbourOfParticleIdx(i){
32	        let neighbours = [];
33	        let pos = this.particles[i].position;
34	
35	        let particleGridX = parseInt(pos.x / this.cellSize);
36	        let particleGridY = parseInt(pos.y / this.cellSize);
37	
38	
39	        for(let x = -1; x <= 1; x++){
40	            for(let y = -1; y <= 1; y++){
41	                let gridX = particleGridX + x;
42	                let gridY = particleGridY + y;
43	
44	                let hashId = this.cellIndexToHash(gridX, gridY);
45	                let content = this.getContentOffCell(hashId);
46	
47	                neighbours.push(...content);
48	            }
49	        }
50	
51	        return neighbours;
52	    }
53	
54	    mapParticleToCell(){
55	        for(let i=0; i<this.particles.length; i++){
56	            let pos = this.particles[i].position;
57	            let hash = this.getGridHashFromPos(pos);
58	
59	            let entries = this.hashMap.get(hash);
60	            if(entries == null){
61	                let newArray = [i];
62	                this.hashMap.set(hash, newArray);
63	            }else{
64	                entries.push(i);
65	            }
66	        }
67	    }
68	
69	    getContentOffCell(id){
70	        let content = this.hashMap.get(id);
71	        if(content == null){
72	            return [];
73	        }else{
74	            return content;
75	        }
76	    }
77	}

