271	        let tiltFlow = Math.pow(downward, 1.85);
272	        let neckBelowCenter = Math.max(0, (this.bottle.center.y - mouth.y) / totalLength);
273	        tiltFlow = Math.max(tiltFlow, Math.pow(neckBelowCenter, 1.35) * 0.55);
