317	        let b = this.bottle;
318	        let bodyTop = -b.bodyLength * 0.5;
319	
320	        if(localY < bodyTop){
321	            return b.neckWidth * 0.42;
322	        }
323	
324	        if(localY < bodyTop + 56){
325	            let shoulder = Math.max(0, Math.min(1, (localY - bodyTop) / 56));
326	            return b.neckWidth * 0.42 + (b.bodyWidth * 0.38 - b.neckWidth * 0.42) * shoulder;
327	        }
328	
329	        return b.bodyWidth * 0.38;
330	    }
