333	        let local = this.bottleWorldToLocal(pos);
334	        let mouthY = this.getBottleOpenY();
335	        let bottomY = this.getBottleBottomY();
336	        let halfWidth = this.getBottleInteriorHalfWidth(local.y) + margin;
337	        return local.y > mouthY - margin &&
338	            local.y < bottomY + margin &&
339	            local.x > -halfWidth &&
340	            local.x < halfWidth;
341	    }
