343	    moveBottleContents(delta){
344	        for(let i=0; i<this.particles.length; i++){
345	            let p = this.particles[i];
346	            if(p.inBottle && this.isInsideBottleInterior(p.position, 8)){
347	                p.position = Add(p.position, delta);
348	                p.prevPosition = Add(p.prevPosition, delta);
349	            }
350	        }
351	    }
