353	    constrainBottle(dt){
354	        let mouthY = this.getBottleOpenY();
355	        let bottomY = this.getBottleBottomY();
356	
357	        for(let i=0; i<this.particles.length; i++){
358	            let p = this.particles[i];
359	            if(!p.inBottle){
360	                continue;
361	            }
362	
363	            let local = this.bottleWorldToLocal(p.position);
364	
365	            if(local.y < mouthY - 10){
366	                p.inBottle = false;
367	                p.turbulence = Math.min(1, p.turbulence + 0.08);
368	                continue;
369	            }
370	
371	            if(local.y < mouthY - 8 || local.y > bottomY + 28){
372	                continue;
373	            }
374	
375	            let clamped = false;
376	
377	            if(local.y > bottomY){
378	                local.y = bottomY;
379	                clamped = true;
380	            }
381	
382	            if(local.y >= mouthY){
383	                let halfWidth = this.getBottleInteriorHalfWidth(local.y);
384	                if(local.x < -halfWidth){
385	                    local.x = -halfWidth;
386	                    clamped = true;
387	                }else if(local.x > halfWidth){
388	                    local.x = halfWidth;
389	                    clamped = true;
390	                }
391	            }
392	
393	            if(clamped){
394	                let velocity = p.velocity.Cpy();
395	                p.position = this.bottleLocalToWorld(local);
396	                p.prevPosition = Sub(p.position, Scale(velocity, dt * 0.22));
397	                p.velocity = Scale(velocity, 0.55);
398	                p.turbulence = Math.min(1, p.turbulence + 0.035);
399	            }
400	        }
401	    }
402	
403	    updateBottleVolume(){
