570	            let wasInside = prevLocal.x > -this.getGlassInteriorHalfWidth(prevLocal.y) &&
571	                prevLocal.x < this.getGlassInteriorHalfWidth(prevLocal.y) &&
572	                prevLocal.y > top &&
573	                prevLocal.y < bottom;
574	
575	            if(!wasInside){
576	                continue;
577	            }
578	
579	            let local = this.worldToGlassLocal(p.position);
580	            let clamped = false;
581	
582	            if(local.y > bottom){
583	                local.y = bottom;
584	                clamped = true;
585	            }
586	
587	            if(local.y > top + 4 && local.y < bottom + 8){
588	                let halfWidth = this.getGlassInteriorHalfWidth(local.y);
589	                if(local.x < -halfWidth){
590	                    local.x = -halfWidth;
591	                    clamped = true;
592	                }else if(local.x > halfWidth){
593	                    local.x = halfWidth;
594	                    clamped = true;
595	                }
596	            }
597	
598	            if(clamped){
599	                let velocity = p.velocity.Cpy();
600	                p.position = this.glassLocalToWorld(local);
601	                p.prevPosition = Sub(p.position, Scale(velocity, dt * 0.28));
