699	    doubleDensityRelaxation(dt){
700	        for(let i=0; i< this.particles.length; i++){
701	            let density = 0;
702	            let densityNear = 0;
703	            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
704	            let particleA = this.particles[i];
705	
706	            for(let j = 0; j < neighbours.length;j++){
707	                let particleB = this.particles[neighbours[j]];
708	                if(particleA == particleB) continue;
709	
710	                let rij = Sub(particleB.position,particleA.position);
711	                let q = rij.Length() / this.INTERACTION_RADIUS;
712	
713	                if(q < 1){
714	                    let oneMinusQ = (1-q);
715	                    density += oneMinusQ*oneMinusQ;
716	                    densityNear += oneMinusQ*oneMinusQ*oneMinusQ;
717	                }
718	            }
719	
720	            let pressure = this.K * (density - this.REST_DENSITY);
721	            let pressureNear = this.K_NEAR * densityNear;
722	            let particleADisplacement = Vector2.Zero();
723	
724	            for(let j=0; j< neighbours.length; j++){
725	                let particleB = this.particles[neighbours[j]];
726	                if(particleA == particleB){
727	                    continue;
728	                }
729	
730	                let rij = Sub(particleB.position, particleA.position);
731	                let distance = rij.Length();
732	                if(distance < 0.0001){
733	                    rij = new Vector2(Math.random() - 0.5, Math.random() - 0.5);
734	                    distance = rij.Length();
735	                }
736	
737	                let q = distance / this.INTERACTION_RADIUS;
738	
739	                if(q < 1.0){
740	                    rij.Normalize();
741	                    let displacementTerm = Math.pow(dt, 2) *
742	                        (pressure * (1-q) + pressureNear * Math.pow(1-q, 2));
743	                    let D = Scale(rij, displacementTerm);
744	
745	                    particleB.position = Add(particleB.position, Scale(D,0.5));
746	                    particleADisplacement = Sub(particleADisplacement, Scale(D,0.5));
747	                }
748	            }
749	
750	            particleA.position = Add(particleA.position, particleADisplacement);
751	        }
752	    }
