754	    viscosity(dt){
755	        for(let i=0; i< this.particles.length; i++){
756	            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
757	            let particleA = this.particles[i];
758	
759	            for(let j = 0; j < neighbours.length;j++){
760	                let particleB = this.particles[neighbours[j]];
761	                if(particleA == particleB) continue;
762	
763	                let rij = Sub(particleB.position,particleA.position);
764	                let velocityA = particleA.velocity;
765	                let velocityB = particleB.velocity;
766	                let distance = rij.Length();
767	                if(distance < 0.0001){
768	                    continue;
769	                }
770	
771	                let q = distance / this.INTERACTION_RADIUS;
772	
773	                if(q < 1){
774	                    rij.Normalize();
775	                    let u = Sub(velocityA, velocityB).Dot(rij);
776	
777	                    if(u > 0){
778	                        let ITerm = dt * (1-q) * (this.SIGMA * u + this.BETA * u * u);
779	                        let I = Scale(rij, ITerm);
780	
781	                        particleA.velocity = Sub(particleA.velocity, Scale(I, 0.5));
782	                        particleB.velocity = Add(particleB.velocity, Scale(I, 0.5));
783	                    }
784	                }
785	            }
786	        }
787	    }
