class Simulation{
    constructor(){
        this.particles = [];
        this.shapes = [];
        this.springs = new Map();
        this.foamParticles = [];

        this.MAX_PARTICLES = 3600;
        this.MAX_FOAM_PARTICLES = 1500;
        this.VELOCITY_DAMPING = 0.998;
        this.GRAVITY = new Vector2(0, 3.35);
        this.REST_DENSITY = 7.1;
        this.K_NEAR = 5.6;
        this.K = 0.62;
        this.INTERACTION_RADIUS = 16;

        this.SIGMA = 0.025;
        this.BETA = 0.012;

        this.GAMMA = 0.1;
        this.PLASTICITY = 0.9;
        this.SPRING_STIFFNESS = 1;

        this.BOTTLE_CAPACITY_L = 1.0;
        this.GLASS_CAPACITY_L = 0.5;
        this.PARTICLE_LITERS = 1 / 1800;
        this.bottleVolumeL = this.BOTTLE_CAPACITY_L;
        this.pourAmount = 0;
        this.foamSpawnDebt = 0;
        this.frame = 0;

        this.glass = {
            center: new Vector2(575, 520),
            angle: Math.PI / 4,
            topWidth: 205,
            bottomWidth: 126,
            height: 270,
            wall: 28
        };

        this.createGlass();

        this.fluidHashGrid = new FluidHashGrid(this.INTERACTION_RADIUS);
        this.fluidHashGrid.initialize(this.particles);

        this.bottle = {
            center: new Vector2(1010, 330),
            angle: Math.PI / 2,
            mouth: new Vector2(1010, 105),
            axis: new Vector2(0, 1),
            pourDir: new Vector2(0, -1),
            flowScale: 0,
            neckLength: 128,
            bodyLength: 322,
            neckWidth: 54,
            bodyWidth: 106
        };

        this.updateBottleFromPour();
        this.createBottleParticles();
        this.updateBottleVolume();
    }

    createBottleParticles(){
        let b = this.bottle;
        let total = Math.round(this.BOTTLE_CAPACITY_L / this.PARTICLE_LITERS);
        let spacing = 3.8;
        let rows = [];
        let liquidTop = -b.bodyLength * 0.5 - b.neckLength * 0.62;
        let liquidBottom = b.bodyLength * 0.5 - 13;

        for(let y=liquidBottom; y>=liquidTop; y-=spacing){
            let width = b.bodyWidth * 0.76;
            if(y < -b.bodyLength * 0.5){
                width = b.neckWidth * 0.48;
            }else if(y < -b.bodyLength * 0.5 + 52){
                let shoulder = Math.max(0, Math.min(1, (y + b.bodyLength * 0.5) / 52));
                width = b.neckWidth * 0.48 + (b.bodyWidth * 0.76 - b.neckWidth * 0.48) * shoulder;
            }

            let row = [];
            for(let x=-width * 0.5; x<=width * 0.5; x+=spacing){
                row.push(new Vector2(x + (Math.random() - 0.5) * 1.6, y + (Math.random() - 0.5) * 1.6));
            }
            rows.push(row);
        }

        let flat = [];
        for(let i=0; i<rows.length; i++){
            flat.push(...rows[i]);
        }

        for(let i=0; i<Math.min(total, flat.length); i++){
            let particle = new Particle(Vector2.Zero());
            particle.position = this.bottleLocalToWorld(flat[i]);
            particle.prevPosition = particle.position.Cpy();
            particle.foam = Math.random() * 0.04;
            particle.inBottle = true;
            this.particles.push(particle);
        }
    }

    setPourAmount(value){
        this.pourAmount = Math.max(0, Math.min(1, value));
        this.bottle.angle = Math.PI / 2 - this.pourAmount * Math.PI * 1.05;
        this.updateBottleFromPour();
    }

    setBottleCenter(position){
        let delta = Sub(position, this.bottle.center);
        this.moveBottleContents(delta);
        this.bottle.center = position.Cpy();
        this.updateBottleFromPour();
        this.resolveBottleGlassCollision();
    }

    rotateBottle(deltaAngle){
        let previousAngle = this.bottle.angle;
        this.bottle.angle += deltaAngle;
        this.bottle.angle = Math.max(-Math.PI * 0.78, Math.min(Math.PI * 1.18, this.bottle.angle));
        this.updateBottleFromPour();
        if(this.getBottleGlassCorrection().Length2() > 0){
            this.bottle.angle = previousAngle;
            this.updateBottleFromPour();
        }
        this.resolveBottleGlassCollision();
    }

    createGlass(){
        this.shapes = [];
        let g = this.glass;
        let wallColor = "rgba(185,225,255,0.72)";

        let topY = -g.height * 0.5;
        let bottomY = g.height * 0.5;
        let leftTop = new Vector2(-g.topWidth * 0.5, topY);
        let rightTop = new Vector2(g.topWidth * 0.5, topY);
        let leftBottom = new Vector2(-g.bottomWidth * 0.5, bottomY);
        let rightBottom = new Vector2(g.bottomWidth * 0.5, bottomY);

        this.leftGlassWall = this.createSegmentCollider(leftTop, leftBottom, g.wall, wallColor);
        this.rightGlassWall = this.createSegmentCollider(rightBottom, rightTop, g.wall, wallColor);
        this.glassBase = this.createSegmentCollider(leftBottom, rightBottom, g.wall * 1.25, wallColor);

        this.shapes.push(this.leftGlassWall);
        this.shapes.push(this.rightGlassWall);
        this.shapes.push(this.glassBase);
    }

    createSegmentCollider(localA, localB, thickness, color){
        let direction = Sub(localB, localA);
        direction.Normalize();
        let normal = direction.GetNormal();
        let half = thickness * 0.5;

        let vertices = [
            this.glassLocalToWorld(Add(localA, Scale(normal, -half))),
            this.glassLocalToWorld(Add(localB, Scale(normal, -half))),
            this.glassLocalToWorld(Add(localB, Scale(normal, half))),
            this.glassLocalToWorld(Add(localA, Scale(normal, half)))
        ];

        let polygon = new Polygon(vertices, color);
        let center = this.glassLocalToWorld(Scale(Add(localA, localB), 0.5));
        if(!polygon.isPointInside(center)){
            vertices.reverse();
            polygon = new Polygon(vertices, color);
        }

        return polygon;
    }

    createOrientedBox(localCenter, width, height, color){
        let corners = [
            new Vector2(-width * 0.5, -height * 0.5),
            new Vector2(width * 0.5, -height * 0.5),
            new Vector2(width * 0.5, height * 0.5),
            new Vector2(-width * 0.5, height * 0.5)
        ];

        let vertices = [];
        for(let i=0; i<corners.length; i++){
            vertices.push(this.glassLocalToWorld(Add(localCenter, corners[i])));
        }

        return new Polygon(vertices, color);
    }

    glassLocalToWorld(local){
        let c = Math.cos(this.glass.angle);
        let s = Math.sin(this.glass.angle);
        return new Vector2(
            this.glass.center.x + local.x * c - local.y * s,
            this.glass.center.y + local.x * s + local.y * c
        );
    }

    worldToGlassLocal(world){
        let c = Math.cos(this.glass.angle);
        let s = Math.sin(this.glass.angle);
        let dx = world.x - this.glass.center.x;
        let dy = world.y - this.glass.center.y;
        return new Vector2(dx * c + dy * s, -dx * s + dy * c);
    }

    isInsideGlassInterior(pos){
        let local = this.worldToGlassLocal(pos);
        let g = this.glass;
        let halfWidth = this.getGlassInteriorHalfWidth(local.y);
        return local.x > -halfWidth &&
            local.x < halfWidth &&
            local.y > -g.height * 0.5 &&
            local.y < g.height * 0.5 - g.wall;
    }

    getGlassInteriorHalfWidth(localY){
        let g = this.glass;
        let y01 = Math.max(0, Math.min(1, (localY + g.height * 0.5) / g.height));
        let widthAtY = g.topWidth + (g.bottomWidth - g.topWidth) * y01;
        return Math.max(12, widthAtY * 0.5 - g.wall);
    }

    getGlassRimCenter(){
        return this.glassLocalToWorld(new Vector2(18, -this.glass.height * 0.5 - 12));
    }

    getShapeAt(pos){
        for(let i=0; i< this.shapes.length; i++){
            if(this.shapes[i].isPointInside(pos)){
                return this.shapes[i];
            }
        }
        return null;
    }

    update(dt){
        this.frame++;
        this.updateBottleFromPour();

        this.neighbourSearch();
        this.updateBottleVolume();

        this.applyGravity(dt);
        this.applyBeerForces(dt);
        this.viscosity(dt);
        this.predictPositions(dt);
        this.constrainBottle(dt);
        this.constrainGlassCrossing(dt);

        for(let i=0; i<2; i++){
            this.doubleDensityRelaxation(dt);
            this.constrainBottle(dt);
            this.constrainGlassCrossing(dt);
        }

        this.handleOneWayCoupling(dt);
        this.worldBoundary();
        this.computeNextVelocity(dt);
        this.ageBeerAndCreateFoam(dt);
        this.updateFoamParticles(dt);
        this.trimParticles();
        this.updateBottleVolume();
    }

    updateBottleFromPour(){
        let totalLength = this.bottle.neckLength + this.bottle.bodyLength;
        let axis = new Vector2(Math.cos(this.bottle.angle), Math.sin(this.bottle.angle));
        let mouth = Sub(this.bottle.center, Scale(axis, totalLength * 0.5));
        let mouthOut = Scale(axis, -1);
        let downward = Math.max(0, mouthOut.y);
        let tiltFlow = Math.pow(downward, 1.85);
        let neckBelowCenter = Math.max(0, (this.bottle.center.y - mouth.y) / totalLength);
        tiltFlow = Math.max(tiltFlow, Math.pow(neckBelowCenter, 1.35) * 0.55);
        tiltFlow = Math.min(1, tiltFlow);

        let pourDir = Add(Scale(mouthOut, 0.72), new Vector2(0, 0.92));
        pourDir.Normalize();

        this.bottle.mouth = mouth;
        this.bottle.axis = axis;
        this.bottle.pourDir = pourDir;
        this.pourAmount = this.bottleVolumeL <= 0 ? 0 : tiltFlow;

        this.bottle.flowScale = this.pourAmount;
    }

    bottleLocalToWorld(local){
        let axis = this.bottle.axis;
        let normal = axis.GetNormal();
        normal.Normalize();
        let bodyCenter = Add(this.bottle.mouth, Scale(axis, this.bottle.neckLength + this.bottle.bodyLength * 0.5));
        return Add(bodyCenter, Add(Scale(normal, local.x), Scale(axis, local.y)));
    }

    bottleWorldToLocal(world){
        let axis = this.bottle.axis;
        let normal = axis.GetNormal();
        normal.Normalize();
        let bodyCenter = Add(this.bottle.mouth, Scale(axis, this.bottle.neckLength + this.bottle.bodyLength * 0.5));
        let delta = Sub(world, bodyCenter);
        return new Vector2(delta.Dot(normal), delta.Dot(axis));
    }

    getBottleMouthY(){
        return -this.bottle.bodyLength * 0.5 - this.bottle.neckLength;
    }

    getBottleOpenY(){
        return this.getBottleMouthY() + 42;
    }

    getBottleBottomY(){
        return this.bottle.bodyLength * 0.5 - 12;
    }

    getBottleInteriorHalfWidth(localY){
        let b = this.bottle;
        let bodyTop = -b.bodyLength * 0.5;

        if(localY < bodyTop){
            return b.neckWidth * 0.42;
        }

        if(localY < bodyTop + 56){
            let shoulder = Math.max(0, Math.min(1, (localY - bodyTop) / 56));
            return b.neckWidth * 0.42 + (b.bodyWidth * 0.38 - b.neckWidth * 0.42) * shoulder;
        }

        return b.bodyWidth * 0.38;
    }

    isInsideBottleInterior(pos, margin = 0){
        let local = this.bottleWorldToLocal(pos);
        let mouthY = this.getBottleOpenY();
        let bottomY = this.getBottleBottomY();
        let halfWidth = this.getBottleInteriorHalfWidth(local.y) + margin;
        return local.y > mouthY - margin &&
            local.y < bottomY + margin &&
            local.x > -halfWidth &&
            local.x < halfWidth;
    }

    moveBottleContents(delta){
        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            if(p.inBottle && this.isInsideBottleInterior(p.position, 8)){
                p.position = Add(p.position, delta);
                p.prevPosition = Add(p.prevPosition, delta);
            }
        }
    }

    constrainBottle(dt){
        let mouthY = this.getBottleOpenY();
        let bottomY = this.getBottleBottomY();

        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            if(!p.inBottle){
                continue;
            }

            let local = this.bottleWorldToLocal(p.position);

            if(local.y < mouthY - 10){
                p.inBottle = false;
                p.turbulence = Math.min(1, p.turbulence + 0.08);
                continue;
            }

            if(local.y < mouthY - 8 || local.y > bottomY + 28){
                continue;
            }

            let clamped = false;

            if(local.y > bottomY){
                local.y = bottomY;
                clamped = true;
            }

            if(local.y >= mouthY){
                let halfWidth = this.getBottleInteriorHalfWidth(local.y);
                if(local.x < -halfWidth){
                    local.x = -halfWidth;
                    clamped = true;
                }else if(local.x > halfWidth){
                    local.x = halfWidth;
                    clamped = true;
                }
            }

            if(clamped){
                let velocity = p.velocity.Cpy();
                p.position = this.bottleLocalToWorld(local);
                p.prevPosition = Sub(p.position, Scale(velocity, dt * 0.22));
                p.velocity = Scale(velocity, 0.55);
                p.turbulence = Math.min(1, p.turbulence + 0.035);
            }
        }
    }

    updateBottleVolume(){
        let count = 0;
        for(let i=0; i<this.particles.length; i++){
            if(this.particles[i].inBottle && this.isInsideBottleInterior(this.particles[i].position, 2)){
                count++;
            }
        }
        this.bottleVolumeL = count * this.PARTICLE_LITERS;
    }

    getBottleCollisionSamples(){
        let samples = [];
        let b = this.bottle;
        let ys = [
            this.getBottleMouthY() + 12,
            -b.bodyLength * 0.5 - b.neckLength * 0.45,
            -b.bodyLength * 0.5 + 18,
            -b.bodyLength * 0.22,
            b.bodyLength * 0.08,
            b.bodyLength * 0.34,
            this.getBottleBottomY()
        ];

        for(let i=0; i<ys.length; i++){
            let y = ys[i];
            let half = this.getBottleInteriorHalfWidth(y) + 12;
            samples.push(this.bottleLocalToWorld(new Vector2(-half, y)));
            samples.push(this.bottleLocalToWorld(new Vector2(half, y)));
            samples.push(this.bottleLocalToWorld(new Vector2(0, y)));
        }

        return samples;
    }

    getBottleGlassCorrection(){
        let correction = Vector2.Zero();
        let samples = this.getBottleCollisionSamples();

        for(let i=0; i<samples.length; i++){
            for(let j=0; j<this.shapes.length; j++){
                let dir = this.shapes[j].getDirectionOut(samples[i]);
                if(dir != null && dir.Length2() > correction.Length2()){
                    correction = dir;
                }
            }
        }

        return correction;
    }

    resolveBottleGlassCollision(){
        for(let iter=0; iter<12; iter++){
            let correction = this.getBottleGlassCorrection();
            if(correction.Length2() < 0.0001){
                return;
            }

            correction = Scale(correction, 1.35);
            this.bottle.center = Add(this.bottle.center, correction);
            this.moveBottleContents(correction);
            this.updateBottleFromPour();
        }
    }

    smoothStep(t){
        return t * t * (3 - 2 * t);
    }

    getGlassBeerVolumeL(){
        let count = 0;
        for(let i=0; i<this.particles.length; i++){
            if(this.isInsideGlassInterior(this.particles[i].position)){
                count++;
            }
        }
        return count * this.PARTICLE_LITERS;
    }

    getGlassFill01(){
        return Math.max(0, Math.min(1, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
    }

    getGlassSurfaceLocalY(){
        let fill = Math.max(0, Math.min(1.15, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
        let bottom = this.glass.height * 0.5 - this.glass.wall;
        let usableHeight = this.glass.height * 0.78;
        return bottom - usableHeight * fill;
    }

    neighbourSearch(){
        this.fluidHashGrid.clearGrid();
        this.fluidHashGrid.mapParticleToCell();
    }

    applyGravity(dt){
        for(let i=0; i< this.particles.length; i++){
            this.particles[i].velocity = Add(this.particles[i].velocity, Scale(this.GRAVITY, dt));
        }
    }

    applyBeerForces(dt){
        let glassVolume = this.getGlassBeerVolumeL();
        let overflow = Math.max(0, (glassVolume - this.GLASS_CAPACITY_L) / this.GLASS_CAPACITY_L);
        let rimOut = new Vector2(-0.8, -0.2);
        rimOut.Normalize();

        for(let i=0; i<this.particles.length; i++){
            let particle = this.particles[i];
            if(this.isInsideGlassInterior(particle.position)){
                particle.velocity = Scale(particle.velocity, 0.999);
                particle.velocity.x += Math.sin((particle.age * 4 + i) * 0.31) * 0.018 * this.pourAmount;

                if(overflow > 0){
                    let local = this.worldToGlassLocal(particle.position);
                    let surfaceBias = Math.max(0, 1 - (local.y + this.glass.height * 0.5) / (this.glass.height * 0.42));
                    particle.velocity = Add(particle.velocity, Scale(rimOut, overflow * surfaceBias * dt * 7.5));
                }
            }
        }
    }

    predictPositions(dt){
        for(let i=0; i< this.particles.length; i++){
            this.particles[i].prevPosition = this.particles[i].position.Cpy();
            let positionDelta = Scale(this.particles[i].velocity, dt * this.VELOCITY_DAMPING);
            this.particles[i].position = Add(this.particles[i].position, positionDelta);
        }
    }

    computeNextVelocity(dt){
        for(let i=0; i< this.particles.length; i++){
            let velocity = Scale(Sub(this.particles[i].position, this.particles[i].prevPosition), 1.0 / dt);
            this.particles[i].velocity = velocity;
        }
    }

    handleOneWayCoupling(dt){
        for(let i=0; i< this.particles.length; i++){
            let particle = this.particles[i];
            for(let j=0; j<this.shapes.length;j++){
                let dir = this.shapes[j].getDirectionOut(particle.position);
                if(dir != null){
                    let speed = particle.velocity.Length();
                    let impact = Math.min(1, Math.max(0, speed - 9) / 48);
                    particle.position = Add(particle.position, dir);
                    if(speed > 0.0001){
                        particle.prevPosition = Sub(particle.position, Scale(particle.velocity, dt * 0.82));
                    }
                    particle.turbulence = Math.min(1, particle.turbulence + impact * 0.42);
                    particle.foam = Math.min(1, particle.foam + impact * 0.16);

                    if(this.isInsideGlassInterior(particle.position) && impact > 0.12){
                        this.createFoamBurst(particle.position, impact * (0.7 + this.pourAmount));
                    }
                }
            }
        }
    }

    constrainGlassCrossing(dt){
        let g = this.glass;
        let top = -g.height * 0.5;
        let bottom = g.height * 0.5 - g.wall;

        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            let prevLocal = this.worldToGlassLocal(p.prevPosition);
            let wasInside = prevLocal.x > -this.getGlassInteriorHalfWidth(prevLocal.y) &&
                prevLocal.x < this.getGlassInteriorHalfWidth(prevLocal.y) &&
                prevLocal.y > top &&
                prevLocal.y < bottom;

            if(!wasInside){
                continue;
            }

            let local = this.worldToGlassLocal(p.position);
            let clamped = false;

            if(local.y > bottom){
                local.y = bottom;
                clamped = true;
            }

            if(local.y > top + 4 && local.y < bottom + 8){
                let halfWidth = this.getGlassInteriorHalfWidth(local.y);
                if(local.x < -halfWidth){
                    local.x = -halfWidth;
                    clamped = true;
                }else if(local.x > halfWidth){
                    local.x = halfWidth;
                    clamped = true;
                }
            }

            if(clamped){
                let velocity = p.velocity.Cpy();
                p.position = this.glassLocalToWorld(local);
                p.prevPosition = Sub(p.position, Scale(velocity, dt * 0.28));
                p.velocity = Scale(velocity, 0.58);
                p.turbulence = Math.min(1, p.turbulence + 0.08);
            }
        }
    }

    ageBeerAndCreateFoam(dt){
        let candidates = [];
        let glassVolume = this.getGlassBeerVolumeL();
        let surfaceY = this.getGlassSurfaceLocalY();

        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            p.age += dt;
            p.turbulence *= 0.972;
            p.foam *= 0.992;

            if(this.isInsideGlassInterior(p.position)){
                let speed = p.velocity.Length();
                let local = this.worldToGlassLocal(p.position);
                let nearSurface = Math.abs(local.y - surfaceY) < 34 || local.y < surfaceY + 22;

                if(speed > 18 || p.turbulence > 0.16){
                    p.foam = Math.min(1, p.foam + 0.008 + p.turbulence * 0.01);
                    if(candidates.length < 110 && Math.random() < 0.055 + this.pourAmount * 0.035){
                        candidates.push(p);
                    }
                }

                if(nearSurface && glassVolume > 0.035){
                    p.foam = Math.min(1, p.foam + 0.005 + this.pourAmount * 0.006);
                    if(candidates.length < 140 && Math.random() < 0.035 + p.foam * 0.03){
                        candidates.push(p);
                    }
                }
            }
        }

        this.foamSpawnDebt += Math.max(0, this.pourAmount - 0.18) * 0.42;
        while(this.foamSpawnDebt > 1 && candidates.length > 0){
            this.foamSpawnDebt -= 1;
            let candidate = candidates[Math.floor(Math.random() * candidates.length)];
            this.createFoamBurst(candidate.position, 0.5 + this.pourAmount * 0.9);
        }
    }

    createFoamBurst(position, intensity){
        if(this.foamParticles.length >= this.MAX_FOAM_PARTICLES){
            return;
        }

        let amount = Math.max(1, Math.floor(1 + intensity * 5));
        for(let i=0; i<amount && this.foamParticles.length < this.MAX_FOAM_PARTICLES; i++){
            let angle = Math.random() * Math.PI * 2;
            let radius = Math.random() * 13 * intensity;
            let pos = Add(position, new Vector2(Math.cos(angle) * radius, Math.sin(angle) * radius));
            let vel = new Vector2(
                (Math.random() - 0.5) * (12 + intensity * 9),
                -8 - Math.random() * (13 + intensity * 8)
            );
            let bubbleRadius = 3.5 + Math.random() * 8 + intensity * 3;
            let life = 0.55 + Math.random() * 0.75 + intensity * 0.7;
            this.foamParticles.push(new FoamParticle(pos, vel, bubbleRadius, life));
        }
    }

    updateFoamParticles(dt){
        for(let i=this.foamParticles.length - 1; i>=0; i--){
            let foam = this.foamParticles[i];
            foam.life -= dt * 0.11;

            if(foam.life <= 0){
                this.foamParticles.splice(i, 1);
                continue;
            }

            foam.prevPosition = foam.position.Cpy();
            foam.velocity.y -= 0.18 * dt;
            foam.velocity.x += Math.sin(foam.seed + foam.life * 8.0) * 0.04;
            foam.velocity = Scale(foam.velocity, 0.982);
            foam.position = Add(foam.position, Scale(foam.velocity, dt));

            for(let j=0; j<this.shapes.length; j++){
                let dir = this.shapes[j].getDirectionOut(foam.position);
                if(dir != null){
                    foam.position = Add(foam.position, dir);
                    foam.velocity = Scale(foam.velocity, 0.64);
                    foam.velocity.y -= 0.2;
                }
            }

            if(foam.position.x < 0 || foam.position.x > canvas.width || foam.position.y < -80 || foam.position.y > canvas.height + 80){
                this.foamParticles.splice(i, 1);
            }
        }
    }

    doubleDensityRelaxation(dt){
        for(let i=0; i< this.particles.length; i++){
            let density = 0;
            let densityNear = 0;
            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
            let particleA = this.particles[i];

            for(let j = 0; j < neighbours.length;j++){
                let particleB = this.particles[neighbours[j]];
                if(particleA == particleB) continue;

                let rij = Sub(particleB.position,particleA.position);
                let q = rij.Length() / this.INTERACTION_RADIUS;

                if(q < 1){
                    let oneMinusQ = (1-q);
                    density += oneMinusQ*oneMinusQ;
                    densityNear += oneMinusQ*oneMinusQ*oneMinusQ;
                }
            }

            let pressure = this.K * (density - this.REST_DENSITY);
            let pressureNear = this.K_NEAR * densityNear;
            let particleADisplacement = Vector2.Zero();

            for(let j=0; j< neighbours.length; j++){
                let particleB = this.particles[neighbours[j]];
                if(particleA == particleB){
                    continue;
                }

                let rij = Sub(particleB.position, particleA.position);
                let distance = rij.Length();
                if(distance < 0.0001){
                    rij = new Vector2(Math.random() - 0.5, Math.random() - 0.5);
                    distance = rij.Length();
                }

                let q = distance / this.INTERACTION_RADIUS;

                if(q < 1.0){
                    rij.Normalize();
                    let displacementTerm = Math.pow(dt, 2) *
                        (pressure * (1-q) + pressureNear * Math.pow(1-q, 2));
                    let D = Scale(rij, displacementTerm);

                    particleB.position = Add(particleB.position, Scale(D,0.5));
                    particleADisplacement = Sub(particleADisplacement, Scale(D,0.5));
                }
            }

            particleA.position = Add(particleA.position, particleADisplacement);
        }
    }

    viscosity(dt){
        for(let i=0; i< this.particles.length; i++){
            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
            let particleA = this.particles[i];

            for(let j = 0; j < neighbours.length;j++){
                let particleB = this.particles[neighbours[j]];
                if(particleA == particleB) continue;

                let rij = Sub(particleB.position,particleA.position);
                let velocityA = particleA.velocity;
                let velocityB = particleB.velocity;
                let distance = rij.Length();
                if(distance < 0.0001){
                    continue;
                }

                let q = distance / this.INTERACTION_RADIUS;

                if(q < 1){
                    rij.Normalize();
                    let u = Sub(velocityA, velocityB).Dot(rij);

                    if(u > 0){
                        let ITerm = dt * (1-q) * (this.SIGMA * u + this.BETA * u * u);
                        let I = Scale(rij, ITerm);

                        particleA.velocity = Sub(particleA.velocity, Scale(I, 0.5));
                        particleB.velocity = Add(particleB.velocity, Scale(I, 0.5));
                    }
                }
            }
        }
    }

    worldBoundary(){
        for(let i=0; i< this.particles.length; i++){
            let pos = this.particles[i].position;

            if(pos.x < 0){
                this.particles[i].position.x = 0;
                this.particles[i].prevPosition.x = 0;
            }
            if(pos.y < 0){
                this.particles[i].position.y = 0;
                this.particles[i].prevPosition.y = 0;
            }
            if(pos.x > canvas.width){
                this.particles[i].position.x = canvas.width-1;
                this.particles[i].prevPosition.x = canvas.width-1;
            }
            if(pos.y > canvas.height){
                this.particles[i].position.y = canvas.height-1;
                this.particles[i].prevPosition.y = canvas.height-1;
            }
        }
    }

    trimParticles(){
        if(this.particles.length > this.MAX_PARTICLES){
            this.particles.splice(0, this.particles.length - this.MAX_PARTICLES);
        }
    }

    drawBeer(targetCtx){
        let r = window.BEER_RADIUS;

        for(let i=0; i < this.particles.length; i++){
            let p = this.particles[i];
            targetCtx.globalAlpha = 0.64 + Math.min(0.28, p.turbulence * 0.22) + Math.min(0.08, p.foam * 0.08);
            targetCtx.beginPath();
            targetCtx.arc(p.position.x, p.position.y, r * (0.92 + p.foam * 0.10), 0, Math.PI * 2);
            targetCtx.fillStyle = "white";
            targetCtx.fill();
        }
        targetCtx.globalAlpha = 1;
    }

    drawFoam(targetCtx){
        for(let i=0; i<this.foamParticles.length; i++){
            let foam = this.foamParticles[i];
            let alpha = Math.max(0, Math.min(1, foam.life / foam.maxLife));
            let r = foam.radius * (0.72 + (1 - alpha) * 0.26);
            targetCtx.globalAlpha = 0.78 * alpha;
            targetCtx.beginPath();
            targetCtx.arc(foam.position.x, foam.position.y, r, 0, Math.PI * 2);
            targetCtx.fillStyle = "white";
            targetCtx.fill();
        }

        let beerFoamRadius = window.FOAM_RADIUS * 0.55;
        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            if(p.foam > 0.22 && this.isInsideGlassInterior(p.position)){
                let r = beerFoamRadius * (0.55 + p.foam * 0.62);
                targetCtx.globalAlpha = Math.min(0.58, p.foam * 0.38);
                targetCtx.beginPath();
                targetCtx.arc(p.position.x, p.position.y, r, 0, Math.PI * 2);
                targetCtx.fillStyle = "white";
                targetCtx.fill();
            }
        }

        targetCtx.globalAlpha = 1;
    }

    drawBeerDetails(targetCtx){
        targetCtx.save();
        targetCtx.globalCompositeOperation = "source-over";

        for(let i=0; i<this.particles.length; i += 5){
            let p = this.particles[i];
            let inGlass = this.isInsideGlassInterior(p.position);
            if(!inGlass && p.turbulence < 0.16){
                continue;
            }

            targetCtx.globalAlpha = Math.min(0.38, 0.08 + p.turbulence * 0.20 + p.foam * 0.12);
            targetCtx.beginPath();
            targetCtx.arc(p.position.x - 2, p.position.y - 3, 1.8 + p.foam * 1.8, 0, Math.PI * 2);
            targetCtx.fillStyle = "#ffe79a";
            targetCtx.fill();

            if(inGlass && i % 15 === 0){
                let bubbleR = 1.4 + ((i * 17) % 5) * 0.45;
                targetCtx.globalAlpha = 0.58;
                targetCtx.beginPath();
                targetCtx.arc(p.position.x + Math.sin(i) * 4, p.position.y - 4 - (i % 7), bubbleR, 0, Math.PI * 2);
                targetCtx.strokeStyle = "rgba(255,245,190,0.82)";
                targetCtx.lineWidth = 1;
                targetCtx.stroke();
            }
        }

        targetCtx.restore();
        targetCtx.globalAlpha = 1;
    }

    drawFoamDetails(targetCtx){
        targetCtx.save();
        targetCtx.lineWidth = 1.2;

        for(let i=0; i<this.foamParticles.length; i++){
            let foam = this.foamParticles[i];
            let alpha = Math.max(0, Math.min(1, foam.life / foam.maxLife));
            let r = foam.radius * (0.58 + (1 - alpha) * 0.18);

            targetCtx.globalAlpha = 0.18 * alpha;
            targetCtx.beginPath();
            targetCtx.arc(foam.position.x + r * 0.22, foam.position.y + r * 0.30, r * 0.92, 0, Math.PI * 2);
            targetCtx.fillStyle = "#8f5b22";
            targetCtx.fill();

            targetCtx.globalAlpha = 0.74 * alpha;
            targetCtx.beginPath();
            targetCtx.arc(foam.position.x, foam.position.y, r, 0, Math.PI * 2);
            targetCtx.fillStyle = "#fff2cf";
            targetCtx.fill();

            targetCtx.globalAlpha = 0.52 * alpha;
            targetCtx.beginPath();
            targetCtx.arc(foam.position.x, foam.position.y, r, 0, Math.PI * 2);
            targetCtx.strokeStyle = "#fffaf0";
            targetCtx.stroke();

            if(i % 3 === 0){
                targetCtx.globalAlpha = 0.72 * alpha;
                targetCtx.beginPath();
                targetCtx.arc(foam.position.x - r * 0.26, foam.position.y - r * 0.32, Math.max(1.2, r * 0.26), 0, Math.PI * 2);
                targetCtx.fillStyle = "#ffffff";
                targetCtx.fill();
            }
        }

        for(let i=0; i<this.particles.length; i += 7){
            let p = this.particles[i];
            if(p.foam < 0.34 || !this.isInsideGlassInterior(p.position)){
                continue;
            }

            let r = 2 + p.foam * 4;
            targetCtx.globalAlpha = Math.min(0.62, p.foam * 0.5);
            targetCtx.beginPath();
            targetCtx.arc(p.position.x, p.position.y - 2, r, 0, Math.PI * 2);
            targetCtx.strokeStyle = "rgba(255,250,235,0.90)";
            targetCtx.stroke();
        }

        targetCtx.restore();
        targetCtx.globalAlpha = 1;
    }

    draw(){
        this.drawGlass();
        this.drawBottle();
        this.drawMeters();
    }

    drawGlass(){
        let g = this.glass;
        let topY = -g.height * 0.5;
        let bottomY = g.height * 0.5;
        let rimA = this.glassLocalToWorld(new Vector2(-g.topWidth * 0.5, topY));
        let rimB = this.glassLocalToWorld(new Vector2(g.topWidth * 0.5, topY));
        let baseA = this.glassLocalToWorld(new Vector2(-g.bottomWidth * 0.5, bottomY));
        let baseB = this.glassLocalToWorld(new Vector2(g.bottomWidth * 0.5, bottomY));
        let capacityY = bottomY - g.height * 0.58;
        let capT = (capacityY + g.height * 0.5) / g.height;
        let capWidth = g.topWidth + (g.bottomWidth - g.topWidth) * capT;
        let capA = this.glassLocalToWorld(new Vector2(-capWidth * 0.5 + 18, capacityY));
        let capB = this.glassLocalToWorld(new Vector2(capWidth * 0.5 - 18, capacityY));

        ctx.save();
        ctx.lineJoin = "round";
        ctx.lineCap = "round";

        ctx.beginPath();
        ctx.moveTo(rimA.x, rimA.y);
        ctx.lineTo(baseA.x, baseA.y);
        ctx.lineTo(baseB.x, baseB.y);
        ctx.lineTo(rimB.x, rimB.y);
        ctx.strokeStyle = "rgba(225,245,255,0.74)";
        ctx.lineWidth = 8;
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(rimA.x, rimA.y);
        ctx.lineTo(rimB.x, rimB.y);
        ctx.strokeStyle = "rgba(255,255,255,0.94)";
        ctx.lineWidth = 5;
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(capA.x, capA.y);
        ctx.lineTo(capB.x, capB.y);
        ctx.strokeStyle = "rgba(255,255,255,0.32)";
        ctx.lineWidth = 2;
        ctx.stroke();

        let shineA = this.glassLocalToWorld(new Vector2(-g.topWidth * 0.28, topY + 26));
        let shineB = this.glassLocalToWorld(new Vector2(-g.bottomWidth * 0.18, bottomY - 44));
        DrawUtils.drawLine(shineA, shineB, "rgba(255,255,255,0.34)", 3);

        ctx.restore();
    }

    drawBottle(){
        let mouth = this.bottle.mouth;
        let axis = this.bottle.axis;
        let normal = axis.GetNormal();
        normal.Normalize();

        let neckLength = this.bottle.neckLength;
        let bodyLength = this.bottle.bodyLength;
        let neckWidth = this.bottle.neckWidth;
        let bodyWidth = this.bottle.bodyWidth;

        let neckCenter = Add(mouth, Scale(axis, neckLength * 0.5));
        let bodyCenter = Add(mouth, Scale(axis, neckLength + bodyLength * 0.5));

        ctx.save();
        ctx.lineJoin = "round";
        ctx.lineCap = "round";

        this.drawOrientedCapsule(bodyCenter, axis, normal, bodyLength, bodyWidth, "rgba(35,24,11,0.86)", "rgba(190,135,42,0.86)", 1);
        this.drawBottleReservoirParticles();
        this.drawOrientedCapsule(bodyCenter, axis, normal, bodyLength, bodyWidth, "rgba(65,42,14,0.28)", "rgba(245,181,68,0.84)", 1);
        this.drawOrientedCapsule(neckCenter, axis, normal, neckLength, neckWidth, "rgba(88,58,18,0.44)", "rgba(230,170,65,0.88)", 1);

        let capCenter = Add(mouth, Scale(axis, 5));
        this.drawOrientedCapsule(capCenter, axis, normal, 18, neckWidth + 7, "#d1aa48", "#ffe0a0", 1);

        let highlightStart = Add(bodyCenter, Add(Scale(normal, -bodyWidth * 0.28), Scale(axis, -bodyLength * 0.35)));
        let highlightEnd = Add(bodyCenter, Add(Scale(normal, -bodyWidth * 0.28), Scale(axis, bodyLength * 0.18)));
        DrawUtils.drawLine(highlightStart, highlightEnd, "rgba(255,226,141,0.42)", 6);

        ctx.restore();
    }

    drawBottleReservoirParticles(){
        ctx.save();
        ctx.globalAlpha = 0.72;
        ctx.fillStyle = "#f0a22a";

        let drawn = 0;
        for(let i=0; i<this.particles.length; i+=2){
            let p = this.particles[i];
            if(!p.inBottle || !this.isInsideBottleInterior(p.position, 2)){
                continue;
            }
            ctx.beginPath();
            ctx.arc(p.position.x, p.position.y, 3.0, 0, Math.PI * 2);
            ctx.fill();
            drawn++;
        }

        ctx.globalAlpha = 0.34;
        ctx.fillStyle = "#ffe083";
        for(let i=0; i<this.particles.length; i+=37){
            let p = this.particles[i];
            if(!p.inBottle || !this.isInsideBottleInterior(p.position, 2)){
                continue;
            }
            ctx.beginPath();
            ctx.arc(p.position.x - 1.5, p.position.y - 1.8, 1.5, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.restore();
    }

    drawMeters(){
        let x = 22;
        let y = 18;
        let w = 240;
        let bottleFill = Math.max(0, Math.min(1, this.bottleVolumeL / this.BOTTLE_CAPACITY_L));
        let glassFill = Math.max(0, Math.min(1.25, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));

        ctx.save();
        ctx.fillStyle = "rgba(18,15,12,0.74)";
        ctx.strokeStyle = "rgba(255,226,150,0.24)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.rect(x, y, w, 70);
        ctx.fill();
        ctx.stroke();

        this.drawMeterLine(x + 14, y + 18, w - 28, bottleFill, "#f2a42c", "Bottle 1.0L");
        this.drawMeterLine(x + 14, y + 46, w - 28, Math.min(1, glassFill), glassFill > 1 ? "#ffcf66" : "#f0b13f", "Glass 0.5L");
        ctx.restore();
    }

    drawMeterLine(x, y, width, fill, color, label){
        ctx.fillStyle = "rgba(255,255,255,0.10)";
        ctx.fillRect(x, y, width, 9);
        ctx.fillStyle = color;
        ctx.fillRect(x, y, width * fill, 9);
        ctx.fillStyle = "rgba(255,245,220,0.82)";
        ctx.font = "12px Arial";
        ctx.fillText(label, x, y - 4);
    }

    drawOrientedCapsule(center, axis, normal, length, width, fill, stroke, alpha){
        let a = Add(center, Scale(axis, -length * 0.5));
        let b = Add(center, Scale(axis, length * 0.5));
        let r = width * 0.5;

        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.moveTo(a.x + normal.x * r, a.y + normal.y * r);
        ctx.lineTo(b.x + normal.x * r, b.y + normal.y * r);
        ctx.lineTo(b.x - normal.x * r, b.y - normal.y * r);
        ctx.lineTo(a.x - normal.x * r, a.y - normal.y * r);
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.strokeStyle = stroke;
        ctx.lineWidth = 3;
        ctx.fill();
        ctx.stroke();
        ctx.globalAlpha = 1;
    }
}

