325	                    particle.foam = Math.min(1, particle.foam + impact * 0.16);
326	
327	                    if(this.isInsideGlassInterior(particle.position) && impact > 0.12){
328	                        this.createFoamBurst(particle.position, impact * (0.7 + this.pourAmount));
329	                    }
330	                }
331	            }
332	        }
333	    }
