335	    ageBeerAndCreateFoam(dt){
336	        let candidates = [];
337	
338	        for(let i=0; i<this.particles.length; i++){
339	            let p = this.particles[i];
340	            p.age += dt;
341	            p.turbulence *= 0.972;
342	            p.foam *= 0.992;
343	
344	            if(this.isInsideGlassInterior(p.position)){
345	                let speed = p.velocity.Length();
346	                if(speed > 18 || p.turbulence > 0.16){
347	                    p.foam = Math.min(1, p.foam + 0.008 + p.turbulence * 0.01);
348	                    if(candidates.length < 110 && Math.random() < 0.055 + this.pourAmount * 0.035){
349	                        candidates.push(p);
350	                    }
351	                }
352	            }
353	        }
354	
355	        this.foamSpawnDebt += Math.max(0, this.pourAmount - 0.18) * 0.42;
356	        while(this.foamSpawnDebt > 1 && candidates.length > 0){
357	            this.foamSpawnDebt -= 1;
358	            let candidate = candidates[Math.floor(Math.random() * candidates.length)];
359	            this.createFoamBurst(candidate.position, 0.5 + this.pourAmount * 0.9);
360	        }
361	    }
