363	    createFoamBurst(position, intensity){
364	        if(this.foamParticles.length >= this.MAX_FOAM_PARTICLES){
365	            return;
366	        }
367	
368	        let amount = Math.max(1, Math.floor(1 + intensity * 5));
369	        for(let i=0; i<amount && this.foamParticles.length < this.MAX_FOAM_PARTICLES; i++){
370	            let angle = Math.random() * Math.PI * 2;
371	            let radius = Math.random() * 13 * intensity;
372	            let pos = Add(position, new Vector2(Math.cos(angle) * radius, Math.sin(angle) * radius));
373	            let vel = new Vector2(
374	                (Math.random() - 0.5) * (12 + intensity * 9),
375	                -8 - Math.random() * (13 + intensity * 8)
376	            );
377	            let bubbleRadius = 3.5 + Math.random() * 8 + intensity * 3;
378	            let life = 0.55 + Math.random() * 0.75 + intensity * 0.7;
379	            this.foamParticles.push(new FoamParticle(pos, vel, bubbleRadius, life));
380	        }
381	    }
