383	    updateFoamParticles(dt){
384	        for(let i=this.foamParticles.length - 1; i>=0; i--){
385	            let foam = this.foamParticles[i];
386	            foam.life -= dt * 0.11;
387	
388	            if(foam.life <= 0){
389	                this.foamParticles.splice(i, 1);
390	                continue;
391	            }
392	
393	            foam.prevPosition = foam.position.Cpy();
394	            foam.velocity.y -= 0.18 * dt;
395	            foam.velocity.x += Math.sin(foam.seed + foam.life * 8.0) * 0.04;
396	            foam.velocity = Scale(foam.velocity, 0.982);
397	            foam.position = Add(foam.position, Scale(foam.velocity, dt));
398	
399	            for(let j=0; j<this.shapes.length; j++){
400	                let dir = this.shapes[j].getDirectionOut(foam.position);
401	                if(dir != null){
402	                    foam.position = Add(foam.position, dir);
403	                    foam.velocity = Scale(foam.velocity, 0.64);
404	                    foam.velocity.y -= 0.2;
405	                }
406	            }
407	
408	            if(foam.position.x < 0 || foam.position.x > canvas.width || foam.position.y < -80 || foam.position.y > canvas.height + 80){
409	                this.foamParticles.splice(i, 1);
410	            }
411	        }
412	    }
413	
414	    doubleDensityRelaxation(dt){
415	        for(let i=0; i< this.particles.length; i++){
416	            let density = 0;
417	            let densityNear = 0;
418	            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
419	            let particleA = this.particles[i];
420	
421	            for(let j = 0; j < neighbours.length;j++){
422	                let particleB = this.particles[neighbours[j]];
423	                if(particleA == particleB) continue;
424	
425	                let rij = Sub(particleB.position,particleA.position);
426	                let q = rij.Length() / this.INTERACTION_RADIUS;
427	
428	                if(q < 1){
429	                    let oneMinusQ = (1-q);
430	                    density += oneMinusQ*oneMinusQ;
431	                    densityNear += oneMinusQ*oneMinusQ*oneMinusQ;
432	                }
433	            }
434	
435	            let pressure = this.K * (density - this.REST_DENSITY);
436	            let pressureNear = this.K_NEAR * densityNear;
437	            let particleADisplacement = Vector2.Zero();
438	
439	            for(let j=0; j< neighbours.length; j++){
440	                let particleB = this.particles[neighbours[j]];
441	                if(particleA == particleB){
442	                    continue;
443	                }
444	
445	                let rij = Sub(particleB.position, particleA.position);
446	                let distance = rij.Length();
447	                if(distance < 0.0001){
448	                    rij = new Vector2(Math.random() - 0.5, Math.random() - 0.5);
449	                    distance = rij.Length();
450	                }
451	
452	                let q = distance / this.INTERACTION_RADIUS;
453	
454	                if(q < 1.0){
455	                    rij.Normalize();
456	                    let displacementTerm = Math.pow(dt, 2) *
457	                        (pressure * (1-q) + pressureNear * Math.pow(1-q, 2));
458	                    let D = Scale(rij, displacementTerm);
459	
460	                    particleB.position = Add(particleB.position, Scale(D,0.5));
461	                    particleADisplacement = Sub(particleADisplacement, Scale(D,0.5));
462	                }
463	            }
464	
465	            particleA.position = Add(particleA.position, particleADisplacement);
466	        }
467	    }
