469	    viscosity(dt){
470	        for(let i=0; i< this.particles.length; i++){
471	            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
472	            let particleA = this.particles[i];
473	
474	            for(let j = 0; j < neighbours.length;j++){
475	                let particleB = this.particles[neighbours[j]];
476	                if(particleA == particleB) continue;
477	
478	                let rij = Sub(particleB.position,particleA.position);
479	                let velocityA = particleA.velocity;
480	                let velocityB = particleB.velocity;
481	                let distance = rij.Length();
482	                if(distance < 0.0001){
483	                    continue;
484	                }
485	
486	                let q = distance / this.INTERACTION_RADIUS;
487	
488	                if(q < 1){
489	                    rij.Normalize();
490	                    let u = Sub(velocityA, velocityB).Dot(rij);
491	
492	                    if(u > 0){
493	                        let ITerm = dt * (1-q) * (this.SIGMA * u + this.BETA * u * u);
494	                        let I = Scale(rij, ITerm);
495	
496	                        particleA.velocity = Sub(particleA.velocity, Scale(I, 0.5));
497	                        particleB.velocity = Add(particleB.velocity, Scale(I, 0.5));
498	                    }
499	                }
500	            }
501	        }
502	    }
