const HTML = "file://" + path.resolve("/home/sprite/fluid-simulation/12. Particle Collisions/Main.html");
const OUT = process.argv[2] || "/tmp/claude-1001/-home-sprite-fluid-simulation/64e1d9f9-4cf1-4554-ad39-a284e1d6702b/scratchpad/shots";

// scenario: array of {label, atMs, action}
// action runs in page context with (playground) available
const browser = await puppeteer.launch({
  headless: true,
  args: ["--no-sandbox", "--disable-setuid-sandbox", "--disable-gpu", "--use-gl=swiftshader", "--single-process"],
});
const page = await browser.newPage();
await page.setViewport({ width: 1320, height: 760, deviceScaleFactor: 1 });
page.on("console", m => { const t = m.text(); if (t.includes("Error") || m.type()==="error") console.log("PAGE:", t); });
page.on("pageerror", e => console.log("PAGEERROR:", e.message));

await page.goto(HTML, { waitUntil: "domcontentloaded", timeout: 60000 });
await page.waitForFunction(() => typeof playground !== "undefined" && typeof Vector2 !== "undefined", { timeout: 15000 });
await new Promise(r => setTimeout(r, 400));

async function shoot(name) {
  const el = await page.$("#canvas");
  await el.screenshot({ path: `${OUT}/${name}.png` });
  console.log("shot", name);
}

// Helper to set a pour pose deterministically
async function pose(cx, cy, angle, holdPour) {
  await page.evaluate((cx, cy, angle, holdPour) => {
    const sim = playground.simulation;
    sim.setBottleCenter(new Vector2(cx, cy));
    if (angle !== null) { sim.bottle.angle = angle; sim.updateBottleFromPour && sim.updateBottleFromPour(); }
    if (playground.setHold) playground.setHold(holdPour);
  }, cx, cy, angle, holdPour);
}

// initial
await shoot("00_initial");

// move into pour pose and pour for a while
await pose(760, 250, Math.PI * 0.5 - 1.15, true);
for (let i = 0; i < 18; i++) {
  await new Promise(r => setTimeout(r, 220));
  if (i === 4) await shoot("01_early_pour");
  if (i === 10) await shoot("02_mid_pour");
}
await shoot("03_late_pour");

// stop pouring, let settle
await pose(820, 230, Math.PI * 0.5, false);
await new Promise(r => setTimeout(r, 1500));
await shoot("04_settled");

await browser.close();
console.log("done");

