class Simulation{
    constructor(){
        this.particles = [];
        this.particleEmitters = [];
        this.shapes = [];
        this.springs = new Map();
        this.foamParticles = [];

        this.MAX_PARTICLES = 2900;
        this.MAX_FOAM_PARTICLES = 1400;
        this.VELOCITY_DAMPING = 0.998;
        this.GRAVITY = new Vector2(0, 3.4);
        this.REST_DENSITY = 7.1;
        this.K_NEAR = 5.6;
        this.K = 0.62;
        this.INTERACTION_RADIUS = 16;

        this.SIGMA = 0.06;
        this.BETA = 0.02;

        this.BOTTLE_CAPACITY_L = 1.0;
        this.GLASS_CAPACITY_L = 0.5;
        this.PARTICLE_LITERS = 1 / 2400;
        this.bottleVolumeL = this.BOTTLE_CAPACITY_L;
        this.pourAmount = 0;
        this.foamSpawnDebt = 0;
        this.headThickness = 0;     // foam head height in the glass (px)
        this.frame = 0;

        // Upright pint glass, sitting near the bottom-left of the stage.
        this.glass = {
            center: new Vector2(545, 470),
            angle: 0,
            topWidth: 210,
            bottomWidth: 138,
            height: 300,
            wall: 24
        };

        this.createGlass();

        this.fluidHashGrid = new FluidHashGrid(this.INTERACTION_RADIUS);
        this.fluidHashGrid.initialize(this.particles);

        // Long-neck beer bottle. Body-local frame: +y points from mouth toward base.
        this.bottle = {
            center: new Vector2(905, 250),
            angle: Math.PI / 2,
            mouth: new Vector2(905, 60),
            axis: new Vector2(0, 1),
            pourDir: new Vector2(0, -1),
            flowScale: 0,
            neckLength: 118,
            bodyLength: 286,
            neckWidth: 44,
            bodyWidth: 116,
            shoulder: 50,
            bottomRound: 26
        };

        this.emitter = this.createParticleEmitter(
            this.bottle.mouth.Cpy(),
            new Vector2(0, -1),
            10,
            0.03,
            6,
            82
        );

        this.updateBottleFromPour();
    }

    createParticleEmitter(position, direction, size, spawnInterval, amount, velocity){
        let emitter = new ParticleEmitter(position, direction, size, spawnInterval, amount, velocity);
        this.particleEmitters.push(emitter);
        return emitter;
    }

    setPourAmount(value){
        this.pourAmount = Math.max(0, Math.min(1, value));
        this.bottle.angle = Math.PI / 2 - this.pourAmount * Math.PI * 1.05;
        this.updateBottleFromPour();
    }

    setBottleCenter(position){
        this.bottle.center = position.Cpy();
        this.updateBottleFromPour();
    }

    setBottleAngle(angle){
        this.bottle.angle = Math.max(-Math.PI * 0.62, Math.min(Math.PI * 0.62 + Math.PI / 2, angle));
        this.updateBottleFromPour();
    }

    rotateBottle(deltaAngle){
        this.setBottleAngle(this.bottle.angle + deltaAngle);
    }

    /* ---------- Glass ---------- */

    createGlass(){
        this.shapes = [];
        let g = this.glass;
        let wallColor = "rgba(150,170,150,0.0)";

        let topY = -g.height * 0.5;
        let bottomY = g.height * 0.5;
        let leftTop = new Vector2(-g.topWidth * 0.5, topY);
        let rightTop = new Vector2(g.topWidth * 0.5, topY);
        let leftBottom = new Vector2(-g.bottomWidth * 0.5, bottomY);
        let rightBottom = new Vector2(g.bottomWidth * 0.5, bottomY);

        this.leftGlassWall = this.createSegmentCollider(leftTop, leftBottom, g.wall, wallColor);
        this.rightGlassWall = this.createSegmentCollider(rightBottom, rightTop, g.wall, wallColor);
        this.glassBase = this.createSegmentCollider(leftBottom, rightBottom, g.wall * 1.4, wallColor);

        this.shapes.push(this.leftGlassWall);
        this.shapes.push(this.rightGlassWall);
        this.shapes.push(this.glassBase);
    }

    createSegmentCollider(localA, localB, thickness, color){
        let direction = Sub(localB, localA);
        direction.Normalize();
        let normal = direction.GetNormal();
        let half = thickness * 0.5;

        let vertices = [
            this.glassLocalToWorld(Add(localA, Scale(normal, -half))),
            this.glassLocalToWorld(Add(localB, Scale(normal, -half))),
            this.glassLocalToWorld(Add(localB, Scale(normal, half))),
            this.glassLocalToWorld(Add(localA, Scale(normal, half)))
        ];

        let polygon = new Polygon(vertices, color);
        let center = this.glassLocalToWorld(Scale(Add(localA, localB), 0.5));
        if(!polygon.isPointInside(center)){
            vertices.reverse();
            polygon = new Polygon(vertices, color);
        }

        return polygon;
    }

    glassLocalToWorld(local){
        let c = Math.cos(this.glass.angle);
        let s = Math.sin(this.glass.angle);
        return new Vector2(
            this.glass.center.x + local.x * c - local.y * s,
            this.glass.center.y + local.x * s + local.y * c
        );
    }

    worldToGlassLocal(world){
        let c = Math.cos(this.glass.angle);
        let s = Math.sin(this.glass.angle);
        let dx = world.x - this.glass.center.x;
        let dy = world.y - this.glass.center.y;
        return new Vector2(dx * c + dy * s, -dx * s + dy * c);
    }

    getGlassInteriorHalfWidth(localY){
        let g = this.glass;
        let y01 = Math.max(0, Math.min(1, (localY + g.height * 0.5) / g.height));
        let widthAtY = g.topWidth + (g.bottomWidth - g.topWidth) * y01;
        return Math.max(10, widthAtY * 0.5 - g.wall);
    }

    isInsideGlassInterior(pos){
        let local = this.worldToGlassLocal(pos);
        let g = this.glass;
        let halfWidth = this.getGlassInteriorHalfWidth(local.y);
        return local.x > -halfWidth &&
            local.x < halfWidth &&
            local.y > -g.height * 0.5 &&
            local.y < g.height * 0.5 - g.wall;
    }

    getGlassBeerVolumeL(){
        let count = 0;
        for(let i=0; i<this.particles.length; i++){
            if(this.isInsideGlassInterior(this.particles[i].position)){
                count++;
            }
        }
        return count * this.PARTICLE_LITERS;
    }

    getGlassFill01(){
        return Math.max(0, Math.min(1, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
    }

    // Local Y of the beer surface inside the glass, derived from how full it is.
    getGlassSurfaceLocalY(){
        let fill = Math.max(0, Math.min(1.12, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
        let bottom = this.glass.height * 0.5 - this.glass.wall;
        let usableHeight = this.glass.height * 0.82;
        return bottom - usableHeight * fill;
    }

    /* ---------- Bottle geometry ---------- */

    updateBottleFromPour(){
        let b = this.bottle;
        let totalLength = b.neckLength + b.bodyLength;
        let axis = new Vector2(Math.cos(b.angle), Math.sin(b.angle));
        let mouth = Sub(b.center, Scale(axis, totalLength * 0.5));
        let mouthOut = Scale(axis, -1);

        // How strongly the mouth points downward -> how fast it pours.
        let downward = Math.max(0, mouthOut.y);
        let tiltFlow = Math.max(0, (downward - 0.12) / 0.8);
        tiltFlow = Math.min(1, tiltFlow);
        tiltFlow = this.smoothStep(tiltFlow);

        let pourDir = Add(Scale(mouthOut, 1.15), new Vector2(0, 0.78));
        pourDir.Normalize();

        b.mouth = mouth;
        b.axis = axis;
        b.pourDir = pourDir;

        let volumeGate = Math.min(1, this.bottleVolumeL / 0.04);
        this.pourAmount = this.bottleVolumeL <= 0 ? 0 : tiltFlow * volumeGate;
        b.flowScale = this.pourAmount;

        // The stream starts a touch outside the lip so it reads as leaving the bottle.
        this.emitter.position = Add(mouth, Scale(pourDir, 6));
        this.emitter.direction = pourDir;
        this.emitter.flowScale = this.pourAmount;
        this.emitter.size = 6 + this.pourAmount * 5;
        this.emitter.amount = 4 + Math.round(this.pourAmount * 7);
        this.emitter.velocity = 64 + this.pourAmount * 44;
        this.emitter.spread = 0.03 + this.pourAmount * 0.06;
    }

    smoothStep(t){
        return t * t * (3 - 2 * t);
    }

    bottleLocalToWorld(local){
        let axis = this.bottle.axis;
        let normal = axis.GetNormal();
        normal.Normalize();
        let bodyCenter = Add(this.bottle.mouth, Scale(axis, this.bottle.neckLength + this.bottle.bodyLength * 0.5));
        return Add(bodyCenter, Add(Scale(normal, local.x), Scale(axis, local.y)));
    }

    // Outer half-width of the bottle silhouette at a given body-local Y.
    bottleHalfWidthOuter(localY){
        let b = this.bottle;
        let bodyTopY = -b.bodyLength * 0.5;
        let bodyBotY = b.bodyLength * 0.5;
        let mouthTipY = bodyTopY - b.neckLength;
        let neckHalf = b.neckWidth * 0.5;
        let bodyHalf = b.bodyWidth * 0.5;

        if(localY < bodyTopY){
            // neck (very slight taper toward the lip)
            let t = Math.max(0, Math.min(1, (localY - mouthTipY) / b.neckLength));
            return neckHalf * (0.9 + 0.1 * t);
        }
        if(localY < bodyTopY + b.shoulder){
            // shoulder: neck -> body
            let t = (localY - bodyTopY) / b.shoulder;
            return neckHalf + (bodyHalf - neckHalf) * this.smoothStep(t);
        }
        if(localY > bodyBotY - b.bottomRound){
            // rounded base corners
            let t = (bodyBotY - localY) / b.bottomRound; // 1 -> 0
            return bodyHalf * Math.sqrt(Math.max(0, 1 - (1 - t) * (1 - t)));
        }
        return bodyHalf;
    }

    // Trace the bottle silhouette (optionally inset) into the given ctx as a closed path.
    traceBottlePath(targetCtx, inset){
        let b = this.bottle;
        let bodyTopY = -b.bodyLength * 0.5;
        let bodyBotY = b.bodyLength * 0.5;
        let mouthTipY = bodyTopY - b.neckLength;
        let step = 6;
        let pts = [];

        for(let y = mouthTipY; y <= bodyBotY; y += step){
            let hw = Math.max(2, this.bottleHalfWidthOuter(y) - inset);
            pts.push(new Vector2(-hw, y));
        }
        for(let y = bodyBotY; y >= mouthTipY; y -= step){
            let hw = Math.max(2, this.bottleHalfWidthOuter(y) - inset);
            pts.push(new Vector2(hw, y));
        }

        targetCtx.beginPath();
        for(let i=0; i<pts.length; i++){
            let w = this.bottleLocalToWorld(pts[i]);
            if(i === 0){
                targetCtx.moveTo(w.x, w.y);
            }else{
                targetCtx.lineTo(w.x, w.y);
            }
        }
        targetCtx.closePath();
    }

    /* ---------- Simulation step ---------- */

    update(dt){
        this.frame++;
        this.updateBottleFromPour();

        this.neighbourSearch();

        let maxSpawnFromBottle = Math.floor(this.bottleVolumeL / this.PARTICLE_LITERS);
        let spawned = this.emitter.spawn(dt, this.particles, this.MAX_PARTICLES, maxSpawnFromBottle);
        if(spawned > 0){
            this.bottleVolumeL = Math.max(0, this.bottleVolumeL - spawned * this.PARTICLE_LITERS);
        }

        this.applyGravity(dt);
        this.applyBeerForces(dt);
        this.viscosity(dt);
        this.predictPositions(dt);

        for(let i=0; i<2; i++){
            this.doubleDensityRelaxation(dt);
        }

        this.handleOneWayCoupling(dt);
        this.worldBoundary();
        this.computeNextVelocity(dt);
        this.ageBeerAndCreateFoam(dt);
        this.updateFoamHead(dt);
        this.updateFoamParticles(dt);
        this.trimParticles();
    }

    neighbourSearch(){
        this.fluidHashGrid.clearGrid();
        this.fluidHashGrid.mapParticleToCell();
    }

    applyGravity(dt){
        for(let i=0; i< this.particles.length; i++){
            this.particles[i].velocity = Add(this.particles[i].velocity, Scale(this.GRAVITY, dt));
        }
    }

    applyBeerForces(dt){
        let glassVolume = this.getGlassBeerVolumeL();
        let overflow = Math.max(0, (glassVolume - this.GLASS_CAPACITY_L) / this.GLASS_CAPACITY_L);
        let rimOut = new Vector2(-0.78, -0.18);
        rimOut.Normalize();

        for(let i=0; i<this.particles.length; i++){
            let particle = this.particles[i];
            if(this.isInsideGlassInterior(particle.position)){
                particle.velocity = Scale(particle.velocity, 0.999);

                if(overflow > 0){
                    let local = this.worldToGlassLocal(particle.position);
                    let surfaceBias = Math.max(0, 1 - (local.y + this.glass.height * 0.5) / (this.glass.height * 0.42));
                    particle.velocity = Add(particle.velocity, Scale(rimOut, overflow * surfaceBias * dt * 8));
                }
            }
        }
    }

    predictPositions(dt){
        for(let i=0; i< this.particles.length; i++){
            this.particles[i].prevPosition = this.particles[i].position.Cpy();
            let positionDelta = Scale(this.particles[i].velocity, dt * this.VELOCITY_DAMPING);
            this.particles[i].position = Add(this.particles[i].position, positionDelta);
        }
    }

    computeNextVelocity(dt){
        for(let i=0; i< this.particles.length; i++){
            let velocity = Scale(Sub(this.particles[i].position, this.particles[i].prevPosition), 1.0 / dt);
            this.particles[i].velocity = velocity;
        }
    }

    handleOneWayCoupling(dt){
        for(let i=0; i< this.particles.length; i++){
            let particle = this.particles[i];
            for(let j=0; j<this.shapes.length;j++){
                let dir = this.shapes[j].getDirectionOut(particle.position);
                if(dir != null){
                    let speed = particle.velocity.Length();
                    let impact = Math.min(1, Math.max(0, speed - 9) / 46);
                    particle.position = Add(particle.position, dir);
                    if(speed > 0.0001){
                        particle.prevPosition = Sub(particle.position, Scale(particle.velocity, dt * 0.8));
                    }
                    particle.turbulence = Math.min(1, particle.turbulence + impact * 0.4);
                    particle.foam = Math.min(1, particle.foam + impact * 0.14);

                    if(this.isInsideGlassInterior(particle.position) && impact > 0.12){
                        this.createFoamBurst(particle.position, impact * (0.6 + this.pourAmount), -0.3);
                    }
                }
            }
        }
    }

    doubleDensityRelaxation(dt){
        for(let i=0; i< this.particles.length; i++){
            let density = 0;
            let densityNear = 0;
            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
            let particleA = this.particles[i];

            for(let j = 0; j < neighbours.length;j++){
                let particleB = this.particles[neighbours[j]];
                if(particleA == particleB) continue;

                let rij = Sub(particleB.position,particleA.position);
                let q = rij.Length() / this.INTERACTION_RADIUS;

                if(q < 1){
                    let oneMinusQ = (1-q);
                    density += oneMinusQ*oneMinusQ;
                    densityNear += oneMinusQ*oneMinusQ*oneMinusQ;
                }
            }

            let pressure = this.K * (density - this.REST_DENSITY);
            let pressureNear = this.K_NEAR * densityNear;
            let particleADisplacement = Vector2.Zero();

            for(let j=0; j< neighbours.length; j++){
                let particleB = this.particles[neighbours[j]];
                if(particleA == particleB){
                    continue;
                }

                let rij = Sub(particleB.position, particleA.position);
                let distance = rij.Length();
                if(distance < 0.0001){
                    rij = new Vector2(Math.random() - 0.5, Math.random() - 0.5);
                    distance = rij.Length();
                }

                let q = distance / this.INTERACTION_RADIUS;

                if(q < 1.0){
                    rij.Normalize();
                    let displacementTerm = Math.pow(dt, 2) *
                        (pressure * (1-q) + pressureNear * Math.pow(1-q, 2));
                    let D = Scale(rij, displacementTerm);

                    particleB.position = Add(particleB.position, Scale(D,0.5));
                    particleADisplacement = Sub(particleADisplacement, Scale(D,0.5));
                }
            }

            particleA.position = Add(particleA.position, particleADisplacement);
        }
    }

    viscosity(dt){
        for(let i=0; i< this.particles.length; i++){
            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
            let particleA = this.particles[i];

            for(let j = 0; j < neighbours.length;j++){
                let particleB = this.particles[neighbours[j]];
                if(particleA == particleB) continue;

                let rij = Sub(particleB.position,particleA.position);
                let velocityA = particleA.velocity;
                let velocityB = particleB.velocity;
                let distance = rij.Length();
                if(distance < 0.0001){
                    continue;
                }

                let q = distance / this.INTERACTION_RADIUS;

                if(q < 1){
                    rij.Normalize();
                    let u = Sub(velocityA, velocityB).Dot(rij);

                    if(u > 0){
                        let ITerm = dt * (1-q) * (this.SIGMA * u + this.BETA * u * u);
                        let I = Scale(rij, ITerm);

                        particleA.velocity = Sub(particleA.velocity, Scale(I, 0.5));
                        particleB.velocity = Add(particleB.velocity, Scale(I, 0.5));
                    }
                }
            }
        }
    }

    worldBoundary(){
        for(let i=0; i< this.particles.length; i++){
            let pos = this.particles[i].position;

            if(pos.x < 0){
                this.particles[i].position.x = 0;
                this.particles[i].prevPosition.x = 0;
            }
            if(pos.y < 0){
                this.particles[i].position.y = 0;
                this.particles[i].prevPosition.y = 0;
            }
            if(pos.x > canvas.width){
                this.particles[i].position.x = canvas.width-1;
                this.particles[i].prevPosition.x = canvas.width-1;
            }
            if(pos.y > canvas.height){
                this.particles[i].position.y = canvas.height-1;
                this.particles[i].prevPosition.y = canvas.height-1;
            }
        }
    }

    trimParticles(){
        // Drop particles that have spilled off the table so they don't pile up forever.
        for(let i=this.particles.length - 1; i>=0; i--){
            let p = this.particles[i];
            if(p.position.y > canvas.height - 4 && !this.isInsideGlassInterior(p.position)){
                p.deadTimer = (p.deadTimer || 0) + 1;
                if(p.deadTimer > 90){
                    this.particles.splice(i, 1);
                }
            }
        }
        if(this.particles.length > this.MAX_PARTICLES){
            this.particles.splice(0, this.particles.length - this.MAX_PARTICLES);
        }
    }

    /* ---------- Foam ---------- */

    ageBeerAndCreateFoam(dt){
        let candidates = [];
        let glassVolume = this.getGlassBeerVolumeL();
        let surfaceY = this.getGlassSurfaceLocalY();
        let impacts = 0;

        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            p.age += dt;
            p.turbulence *= 0.97;
            p.foam *= 0.993;

            if(this.isInsideGlassInterior(p.position)){
                let speed = p.velocity.Length();
                let local = this.worldToGlassLocal(p.position);
                let nearSurface = Math.abs(local.y - surfaceY) < 30;

                if((speed > 16 || p.turbulence > 0.16) && nearSurface){
                    p.foam = Math.min(1, p.foam + 0.02 + p.turbulence * 0.02);
                    impacts += Math.min(1, speed / 40);
                    if(candidates.length < 120 && Math.random() < 0.06 + this.pourAmount * 0.05){
                        candidates.push(p);
                    }
                }
            }
        }

        // The head grows while beer is actively splashing into the pool, then settles.
        let targetGrowth = Math.min(1.4, impacts * 0.06) * this.pourAmount;
        this.headThickness += targetGrowth * 14 * dt;
        let maxHead = 4 + this.getGlassFill01() * 40;
        this.headThickness = Math.min(maxHead, this.headThickness);
        this.headThickness *= (1 - dt * 0.12);            // slow collapse of the head
        if(glassVolume < 0.01){
            this.headThickness *= (1 - dt * 0.9);
        }

        this.foamSpawnDebt += Math.max(0, this.pourAmount - 0.15) * 0.5;
        while(this.foamSpawnDebt > 1 && candidates.length > 0){
            this.foamSpawnDebt -= 1;
            let candidate = candidates[Math.floor(Math.random() * candidates.length)];
            this.createFoamBurst(candidate.position, 0.5 + this.pourAmount * 0.8, -0.4);
        }
    }

    createFoamBurst(position, intensity, upBias = 0){
        if(this.foamParticles.length >= this.MAX_FOAM_PARTICLES){
            return;
        }

        let amount = Math.max(1, Math.floor(1 + intensity * 4));
        for(let i=0; i<amount && this.foamParticles.length < this.MAX_FOAM_PARTICLES; i++){
            let angle = Math.random() * Math.PI * 2;
            let radius = Math.random() * 10 * intensity;
            let pos = Add(position, new Vector2(Math.cos(angle) * radius, Math.sin(angle) * radius));
            let vel = new Vector2(
                (Math.random() - 0.5) * (10 + intensity * 8),
                (-4 + upBias * 6) - Math.random() * (6 + intensity * 6)
            );
            let bubbleRadius = 4 + Math.random() * 7 + intensity * 3;
            let life = 0.7 + Math.random() * 0.9 + intensity * 0.7;
            this.foamParticles.push(new FoamParticle(pos, vel, bubbleRadius, life));
        }
    }

    updateFoamHead(dt){
        // nothing else to integrate; headThickness is advanced in ageBeerAndCreateFoam
    }

    updateFoamParticles(dt){
        let surfaceY = this.getGlassSurfaceLocalY();

        for(let i=this.foamParticles.length - 1; i>=0; i--){
            let foam = this.foamParticles[i];
            foam.life -= dt * 0.12;

            if(foam.life <= 0){
                this.foamParticles.splice(i, 1);
                continue;
            }

            foam.prevPosition = foam.position.Cpy();

            // Foam is buoyant: float up to the beer surface, then rest on the head.
            let local = this.worldToGlassLocal(foam.position);
            let headTop = surfaceY - this.headThickness;
            if(this.isInsideGlassInterior(foam.position) || (local.x > -this.getGlassInteriorHalfWidth(local.y) && local.x < this.getGlassInteriorHalfWidth(local.y))){
                if(local.y > headTop){
                    foam.velocity.y -= (12 + (local.y - headTop) * 0.25) * dt;
                }else{
                    foam.velocity.y += 3 * dt;
                }
            }

            foam.velocity.x += Math.sin(foam.seed + foam.life * 7.0) * 0.05;
            foam.velocity = Scale(foam.velocity, 0.96);
            foam.position = Add(foam.position, Scale(foam.velocity, dt));

            for(let j=0; j<this.shapes.length; j++){
                let dir = this.shapes[j].getDirectionOut(foam.position);
                if(dir != null){
                    foam.position = Add(foam.position, dir);
                    foam.velocity = Scale(foam.velocity, 0.6);
                }
            }

            if(foam.position.x < -20 || foam.position.x > canvas.width + 20 || foam.position.y < -80 || foam.position.y > canvas.height + 40){
                this.foamParticles.splice(i, 1);
            }
        }
    }

    /* ---------- Rendering: beer & foam silhouettes (white on transparent) ---------- */

    drawBeer(targetCtx){
        let r = window.BEER_RADIUS;
        targetCtx.fillStyle = "white";
        targetCtx.globalAlpha = 1;

        for(let i=0; i < this.particles.length; i++){
            let p = this.particles[i];
            targetCtx.beginPath();
            targetCtx.arc(p.position.x, p.position.y, r, 0, Math.PI * 2);
            targetCtx.fill();
        }
    }

    drawFoam(targetCtx){
        targetCtx.fillStyle = "white";
        targetCtx.globalAlpha = 1;

        // Foam head: a creamy band sitting on top of the beer in the glass.
        if(this.headThickness > 1.5 && this.getGlassFill01() > 0.02){
            let surfaceY = this.getGlassSurfaceLocalY();
            let halfTop = this.getGlassInteriorHalfWidth(surfaceY);
            let step = 11;
            for(let x = -halfTop; x <= halfTop; x += step){
                let edge = 1 - Math.min(1, Math.abs(x) / halfTop);
                let dome = this.headThickness * (0.55 + 0.45 * edge);
                let bumps = Math.max(1, Math.floor(dome / 9));
                for(let k=0; k<=bumps; k++){
                    let ly = surfaceY - (dome * k / bumps);
                    let jitter = Math.sin(x * 0.13 + k * 1.7 + this.frame * 0.02) * 4;
                    let w = this.glassLocalToWorld(new Vector2(x + jitter * 0.4, ly));
                    targetCtx.beginPath();
                    targetCtx.arc(w.x, w.y, 9 + edge * 3, 0, Math.PI * 2);
                    targetCtx.fill();
                }
            }
        }

        // Lively bubbles (splash + rising foam).
        for(let i=0; i<this.foamParticles.length; i++){
            let foam = this.foamParticles[i];
            let alpha = Math.max(0, Math.min(1, foam.life / foam.maxLife));
            let r = foam.radius * (0.72 + (1 - alpha) * 0.3);
            targetCtx.beginPath();
            targetCtx.arc(foam.position.x, foam.position.y, r, 0, Math.PI * 2);
            targetCtx.fill();
        }
    }

    drawBeerDetails(targetCtx){
        targetCtx.save();

        // Rising bubbles and bright specular flecks inside the settled beer.
        for(let i=0; i<this.particles.length; i += 6){
            let p = this.particles[i];
            if(!this.isInsideGlassInterior(p.position)){
                continue;
            }
            if(i % 12 === 0){
                let bob = Math.sin(this.frame * 0.05 + i) * 2;
                let bubbleR = 1.1 + ((i * 17) % 5) * 0.4;
                targetCtx.globalAlpha = 0.5;
                targetCtx.beginPath();
                targetCtx.arc(p.position.x + bob, p.position.y - 3, bubbleR, 0, Math.PI * 2);
                targetCtx.strokeStyle = "rgba(255,247,205,0.8)";
                targetCtx.lineWidth = 1;
                targetCtx.stroke();
            }
        }

        targetCtx.restore();
        targetCtx.globalAlpha = 1;
    }

    drawFoamDetails(targetCtx){
        targetCtx.save();

        for(let i=0; i<this.foamParticles.length; i++){
            let foam = this.foamParticles[i];
            let alpha = Math.max(0, Math.min(1, foam.life / foam.maxLife));
            let r = foam.radius * (0.62 + (1 - alpha) * 0.2);

            // little shadow under each bubble for a creamy, dimensional head
            targetCtx.globalAlpha = 0.12 * alpha;
            targetCtx.beginPath();
            targetCtx.arc(foam.position.x + r * 0.18, foam.position.y + r * 0.28, r * 0.9, 0, Math.PI * 2);
            targetCtx.fillStyle = "#caa258";
            targetCtx.fill();

            if(i % 2 === 0){
                targetCtx.globalAlpha = 0.7 * alpha;
                targetCtx.beginPath();
                targetCtx.arc(foam.position.x - r * 0.26, foam.position.y - r * 0.3, Math.max(1, r * 0.24), 0, Math.PI * 2);
                targetCtx.fillStyle = "#ffffff";
                targetCtx.fill();
            }
        }

        targetCtx.restore();
        targetCtx.globalAlpha = 1;
    }

    /* ---------- Rendering: solid props ---------- */

    drawBack(){
        this.drawGlassBack();
        this.drawBottle();
    }

    drawFront(){
        this.drawGlassFront();
    }

    drawGlassBack(){
        let g = this.glass;
        let topY = -g.height * 0.5;
        let bottomY = g.height * 0.5;
        let rimA = this.glassLocalToWorld(new Vector2(-g.topWidth * 0.5, topY));
        let rimB = this.glassLocalToWorld(new Vector2(g.topWidth * 0.5, topY));
        let baseA = this.glassLocalToWorld(new Vector2(-g.bottomWidth * 0.5, bottomY));
        let baseB = this.glassLocalToWorld(new Vector2(g.bottomWidth * 0.5, bottomY));

        ctx.save();
        // faint cool glass body so the beer reads as sitting inside real glass
        ctx.beginPath();
        ctx.moveTo(rimA.x, rimA.y);
        ctx.lineTo(baseA.x, baseA.y);
        ctx.lineTo(baseB.x, baseB.y);
        ctx.lineTo(rimB.x, rimB.y);
        ctx.closePath();
        let body = ctx.createLinearGradient(rimA.x, 0, rimB.x, 0);
        body.addColorStop(0, "rgba(214,226,224,0.30)");
        body.addColorStop(0.5, "rgba(236,243,240,0.12)");
        body.addColorStop(1, "rgba(214,226,224,0.22)");
        ctx.fillStyle = body;
        ctx.fill();
        ctx.restore();
    }

    drawGlassFront(){
        let g = this.glass;
        let topY = -g.height * 0.5;
        let bottomY = g.height * 0.5;
        let rimA = this.glassLocalToWorld(new Vector2(-g.topWidth * 0.5, topY));
        let rimB = this.glassLocalToWorld(new Vector2(g.topWidth * 0.5, topY));
        let baseA = this.glassLocalToWorld(new Vector2(-g.bottomWidth * 0.5, bottomY));
        let baseB = this.glassLocalToWorld(new Vector2(g.bottomWidth * 0.5, bottomY));

        ctx.save();
        ctx.lineJoin = "round";
        ctx.lineCap = "round";

        // body outline
        ctx.beginPath();
        ctx.moveTo(rimA.x, rimA.y);
        ctx.lineTo(baseA.x, baseA.y);
        ctx.lineTo(baseB.x, baseB.y);
        ctx.lineTo(rimB.x, rimB.y);
        ctx.strokeStyle = "rgba(70,82,86,0.45)";
        ctx.lineWidth = 5;
        ctx.stroke();

        // rim (front + back ellipse halves)
        let rimCenter = this.glassLocalToWorld(new Vector2(0, topY));
        ctx.beginPath();
        ctx.ellipse(rimCenter.x, rimCenter.y, g.topWidth * 0.5, 12, this.glass.angle, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(255,255,255,0.85)";
        ctx.lineWidth = 4;
        ctx.stroke();
        ctx.beginPath();
        ctx.ellipse(rimCenter.x, rimCenter.y, g.topWidth * 0.5, 12, this.glass.angle, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(90,100,104,0.30)";
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // base ellipse
        let baseCenter = this.glassLocalToWorld(new Vector2(0, bottomY));
        ctx.beginPath();
        ctx.ellipse(baseCenter.x, baseCenter.y, g.bottomWidth * 0.5, 9, this.glass.angle, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(70,82,86,0.4)";
        ctx.lineWidth = 4;
        ctx.stroke();

        // vertical highlight streaks
        let shineA = this.glassLocalToWorld(new Vector2(-g.topWidth * 0.30, topY + 22));
        let shineB = this.glassLocalToWorld(new Vector2(-g.bottomWidth * 0.26, bottomY - 30));
        DrawUtils.drawLine(shineA, shineB, "rgba(255,255,255,0.5)", 5);
        let shineC = this.glassLocalToWorld(new Vector2(g.topWidth * 0.34, topY + 30));
        let shineD = this.glassLocalToWorld(new Vector2(g.bottomWidth * 0.30, bottomY - 60));
        DrawUtils.drawLine(shineC, shineD, "rgba(255,255,255,0.28)", 3);

        ctx.restore();
    }

    drawBottle(){
        let b = this.bottle;
        let axis = b.axis;
        let normal = axis.GetNormal();
        normal.Normalize();
        let bodyCenter = Add(b.mouth, Scale(axis, b.neckLength + b.bodyLength * 0.5));

        ctx.save();
        ctx.lineJoin = "round";
        ctx.lineCap = "round";

        // --- glass body fill (brown, cylinder shading across the normal) ---
        this.traceBottlePath(ctx, 0);
        let edge0 = Add(bodyCenter, Scale(normal, -b.bodyWidth * 0.5));
        let edge1 = Add(bodyCenter, Scale(normal, b.bodyWidth * 0.5));
        let glass = ctx.createLinearGradient(edge0.x, edge0.y, edge1.x, edge1.y);
        glass.addColorStop(0.0, "#3a1f0c");
        glass.addColorStop(0.32, "#6e3c14");
        glass.addColorStop(0.5, "#norm");
        glass.addColorStop(0.5, "#8a5018");
        glass.addColorStop(0.7, "#5d3110");
        glass.addColorStop(1.0, "#2c1708");
        ctx.fillStyle = glass;
        ctx.fill();

        // beer still inside the bottle (horizontal surface)
        this.drawBottleLiquid();

        // re-stroke the silhouette so the liquid stays tucked inside the glass
        this.traceBottlePath(ctx, 0);
        ctx.strokeStyle = "rgba(20,12,5,0.55)";
        ctx.lineWidth = 3;
        ctx.stroke();

        // glass rim highlight running down one side
        let hi0 = Add(bodyCenter, Add(Scale(normal, -b.bodyWidth * 0.30), Scale(axis, -b.bodyLength * 0.42)));
        let hi1 = Add(bodyCenter, Add(Scale(normal, -b.bodyWidth * 0.30), Scale(axis, b.bodyLength * 0.30)));
        DrawUtils.drawLine(hi0, hi1, "rgba(255,210,140,0.35)", 7);

        // --- label ---
        this.drawBottleLabel(bodyCenter, axis, normal);

        // --- cap ---
        let capCenter = Add(b.mouth, Scale(axis, 7));
        this.drawOrientedCapsule(capCenter, axis, normal, 22, b.neckWidth + 8, "#cBA martin", null);
        this.drawOrientedCapsule(capCenter, axis, normal, 22, b.neckWidth + 8, "#caa23c", "#7a5a18");
        let capTop = Add(b.mouth, Scale(axis, -1));
        this.drawOrientedCapsule(capTop, axis, normal, 5, b.neckWidth + 4, "#e8cd72", null);

        ctx.restore();
    }

    drawBottleLiquid(){
        let fill = Math.max(0, Math.min(1, this.bottleVolumeL / this.BOTTLE_CAPACITY_L));
        if(fill <= 0.001){
            return;
        }

        // World vertical extent of the bottle interior, so the surface stays horizontal.
        let b = this.bottle;
        let bodyTopY = -b.bodyLength * 0.5;
        let bodyBotY = b.bodyLength * 0.5;
        let mouthTipY = bodyTopY - b.neckLength;
        let minY = Infinity;
        let maxY = -Infinity;
        let samples = [
            new Vector2(0, mouthTipY), new Vector2(0, bodyTopY), new Vector2(0, bodyBotY),
            new Vector2(-b.bodyWidth * 0.5, bodyBotY), new Vector2(b.bodyWidth * 0.5, bodyBotY),
            new Vector2(-b.bodyWidth * 0.5, bodyTopY + b.shoulder), new Vector2(b.bodyWidth * 0.5, bodyTopY + b.shoulder)
        ];
        for(let i=0; i<samples.length; i++){
            let w = this.bottleLocalToWorld(samples[i]);
            minY = Math.min(minY, w.y);
            maxY = Math.max(maxY, w.y);
        }
        let surfaceY = maxY - fill * (maxY - minY);

        ctx.save();
        this.traceBottlePath(ctx, 5);
        ctx.clip();

        let grad = ctx.createLinearGradient(0, surfaceY, 0, maxY);
        grad.addColorStop(0, "#ffc34a");
        grad.addColorStop(0.4, "#f0a01f");
        grad.addColorStop(1, "#c5710c");
        ctx.fillStyle = grad;
        ctx.fillRect(0, surfaceY, canvas.width, maxY - surfaceY + 6);

        // bright meniscus line
        ctx.globalAlpha = 0.5;
        ctx.fillStyle = "#ffe39a";
        ctx.fillRect(0, surfaceY, canvas.width, 3);
        ctx.globalAlpha = 1;

        ctx.restore();
    }

    drawBottleLabel(bodyCenter, axis, normal){
        let b = this.bottle;
        let labelHalfLen = b.bodyLength * 0.22;
        let labelHalfW = b.bodyWidth * 0.46;
        let tilt = this.bottle.angle - Math.PI / 2;

        ctx.save();
        ctx.translate(bodyCenter.x, bodyCenter.y);
        ctx.rotate(tilt);

        // label background (cream) with a green band
        this.roundRect(-labelHalfW, -labelHalfLen, labelHalfW * 2, labelHalfLen * 2, 10);
        let lg = ctx.createLinearGradient(-labelHalfW, 0, labelHalfW, 0);
        lg.addColorStop(0, "#e7dcc0");
        lg.addColorStop(0.5, "#fbf3df");
        lg.addColorStop(1, "#e0d3b2");
        ctx.fillStyle = lg;
        ctx.fill();
        ctx.strokeStyle = "rgba(90,70,30,0.35)";
        ctx.lineWidth = 2;
        ctx.stroke();

        ctx.fillStyle = "#2f7d3f";
        this.roundRect(-labelHalfW, -labelHalfLen * 0.42, labelHalfW * 2, labelHalfLen * 0.84, 6);
        ctx.fill();

        ctx.fillStyle = "#fbf3df";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.font = "bold 17px Arial";
        ctx.fillText("HOP", 0, -labelHalfLen * 0.12);
        ctx.font = "bold 13px Arial";
        ctx.fillText("HOUSE", 0, labelHalfLen * 0.16);

        ctx.restore();
    }

    roundRect(x, y, w, h, r){
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.arcTo(x + w, y, x + w, y + h, r);
        ctx.arcTo(x + w, y + h, x, y + h, r);
        ctx.arcTo(x, y + h, x, y, r);
        ctx.arcTo(x, y, x + w, y, r);
        ctx.closePath();
    }

    drawOrientedCapsule(center, axis, normal, length, width, fill, stroke){
        let a = Add(center, Scale(axis, -length * 0.5));
        let b = Add(center, Scale(axis, length * 0.5));
        let r = width * 0.5;

        ctx.beginPath();
        ctx.moveTo(a.x + normal.x * r, a.y + normal.y * r);
        ctx.lineTo(b.x + normal.x * r, b.y + normal.y * r);
        ctx.lineTo(b.x - normal.x * r, b.y - normal.y * r);
        ctx.lineTo(a.x - normal.x * r, a.y - normal.y * r);
        ctx.closePath();
        if(fill){
            ctx.fillStyle = fill;
            ctx.fill();
        }
        if(stroke){
            ctx.strokeStyle = stroke;
            ctx.lineWidth = 2;
            ctx.stroke();
        }
    }
}

