import puppeteer from "puppeteer";
import path from "path";
const HTML = "file://" + path.resolve("/home/sprite/fluid-simulation/12. Particle Collisions/Main.html");
const browser = await puppeteer.launch({ headless: true, args: ["--no-sandbox","--disable-setuid-sandbox","--disable-gpu","--use-gl=swiftshader","--single-process"] });
const page = await browser.newPage();
