  playground.simulation.setBottleCenter(new Vector2(728, 232));
  playground.setHold(true);
});

async function step(frames) {
  await page.evaluate((n) => { for (let k=0;k<n;k++) updatePlayground(1/60); }, frames);
}

for (let t = 0; t < 14; t++) {
  await step(30); // 0.5s of sim
  const info = await page.evaluate(() => {
    const s = playground.simulation;
    let inGlass = 0, belowGlass = 0;
    for (const p of s.particles) {
      if (s.isInsideGlassInterior(p.position)) inGlass++;
      if (p.position.y > 622) belowGlass++;
    }
    return { total: s.particles.length, inGlass, belowGlass,
             bottleL: +s.bottleVolumeL.toFixed(3), glassL: +s.getGlassBeerVolumeL().toFixed(3),
