class Particle{
    constructor(position){
        this.position = position;
        this.prevPosition = position.Cpy();
        this.velocity = Vector2.Zero();
        this.age = 0;
        this.foam = 0;
        this.turbulence = 0;
        this.agitation = 0;
        this.bottleLocal = null;
        this.inBottle = false;
        this.color = "#d38a12";
    }
}

class FoamParticle{
    constructor(position, velocity, radius, life){
        this.position = position;
        this.prevPosition = position.Cpy();
        this.velocity = velocity;
        this.radius = radius;
        this.life = life;
        this.maxLife = life;
        this.seed = Math.random() * Math.PI * 2;
    }
}

