import puppeteer from "puppeteer";
import path from "path";

const HTML = "file://" + path.resolve(process.env.HTML || "/home/sprite/fluid-simulation/12. Particle Collisions/Main.html");
const OUT = process.argv[2] || "/tmp/claude-1001/-home-sprite-fluid-simulation/64e1d9f9-4cf1-4554-ad39-a284e1d6702b/scratchpad/shots";
const CX = +(process.env.CX || 720);
const CY = +(process.env.CY || 232);
const ANG = +(process.env.ANG || -0.7);
const POUR = +(process.env.POUR || 150);   // frames of pouring

const browser = await puppeteer.launch({
  headless: true,
  args: ["--no-sandbox", "--disable-setuid-sandbox", "--disable-gpu", "--use-gl=swiftshader", "--single-process"],
});
const page = await browser.newPage();
await page.setViewport({ width: 1320, height: 760, deviceScaleFactor: 1 });
page.on("pageerror", e => console.log("PAGEERROR:", e.message));
await page.goto(HTML, { waitUntil: "domcontentloaded", timeout: 60000 });
await page.waitForFunction(() => typeof playground !== "undefined" && typeof Vector2 !== "undefined", { timeout: 15000 });

async function shoot(name) {
  const el = await page.$("#canvas");
  await el.screenshot({ path: `${OUT}/${name}.png` });
  console.log("shot", name);
}
// drive deterministically; hold targetAngle each frame
async function run(frames, targetAngle, cx, cy) {
  await page.evaluate((n, a, cx, cy) => {
    if (cx !== null) playground.mousePos = new Vector2(cx, cy);
    for (let k = 0; k < n; k++) { playground.targetAngle = a; updatePlayground(1/60); }
  }, frames, targetAngle, cx, cy);
}

// place bottle, settle upright
await page.evaluate((cx, cy) => { playground.mousePos = new Vector2(cx,cy); playground.simulation.bottle.center = new Vector2(cx,cy); playground.targetAngle = Math.PI/2; playground.angle = Math.PI/2; }, CX, CY);
await run(10, Math.PI/2, CX, CY);
await shoot("00_initial");

// pour
const segs = 4;
for (let s = 0; s < segs; s++) {
  await run(Math.round(POUR/segs), ANG, CX, CY);
  await shoot(`0${s+1}_pour_${s+1}`);
}

// straighten & settle
await run(150, Math.PI/2, CX + 90, CY - 30);
await shoot("9_settled");

await browser.close();
console.log("done");

