import puppeteer from "puppeteer";
import path from "path";
const HTML = "file://" + path.resolve("/home/sprite/fluid-simulation/12. Particle Collisions/Main.html");
const browser = await puppeteer.launch({ headless: true, args: ["--no-sandbox","--disable-setuid-sandbox","--disable-gpu","--use-gl=swiftshader","--single-process"] });
const page = await browser.newPage();
await page.setViewport({ width: 1320, height: 760 });
let errors = [];
page.on("pageerror", e => errors.push(e.message));
page.on("console", m => { if (m.type()==="error") errors.push("console:"+m.text()); });
await page.goto(HTML, { waitUntil: "domcontentloaded", timeout: 60000 });
await page.waitForFunction(() => typeof playground !== "undefined", { timeout: 15000 });

// Drive the REAL control path: keyboard q/w + mouse position.
const res = await page.evaluate(() => {
  const log = {};
  playground.onMouseMove(new Vector2(780, 200));
  const a0 = playground.targetAngle;

  // press Q (tip left / pour) for ~2.5s of sim
  playground.onKeyDown("q");
  for (let k=0;k<150;k++) updatePlayground(1/60);
  playground.onKeyUp("q");
  log.afterQ_angle = +playground.angle.toFixed(2);
  log.afterQ_targetMoved = playground.targetAngle < a0;
  log.glassFillAfterQ = +playground.simulation.getGlassFill01().toFixed(2);
  log.bottleAfterQ = +playground.simulation.bottleVolumeL.toFixed(2);

  // now press W (tip right / back) for a while
  const aQ = playground.targetAngle;
  playground.onKeyDown("w");
  for (let k=0;k<120;k++) updatePlayground(1/60);
  playground.onKeyUp("w");
  log.afterW_targetMoved = playground.targetAngle > aQ;
  log.afterW_angle = +playground.angle.toFixed(2);

  log.glassAngleNow = +playground.simulation.glass.angle.toFixed(2);
  log.particles = playground.simulation.particles.length;
  return log;
});

console.log("errors:", errors.length ? errors : "none");
console.log(JSON.stringify(res, null, 0));
await browser.close();

