import puppeteer from "puppeteer";
import path from "path";
const HTML = "file://" + path.resolve("/home/sprite/fluid-simulation/12. Particle Collisions/Main.html");
const browser = await puppeteer.launch({ headless: true, args: ["--no-sandbox","--disable-setuid-sandbox","--disable-gpu","--use-gl=swiftshader","--single-process"] });
const page = await browser.newPage();
await page.setViewport({ width: 1320, height: 760 });
page.on("pageerror", e => console.log("PAGEERROR:", e.message));
await page.goto(HTML, { waitUntil: "domcontentloaded", timeout: 60000 });
await page.waitForFunction(() => typeof playground !== "undefined", { timeout: 15000 });

// fill the glass to a realistic scene
await page.evaluate(() => {
  playground.mousePos = new Vector2(790, 185);
  playground.simulation.bottle.center = new Vector2(790,185);
  playground.targetAngle = -0.48; playground.angle = -0.48;
  for (let k=0;k<160;k++){ playground.targetAngle = -0.48; updatePlayground(1/60); }
});

const r = await page.evaluate(() => {
  const N = 90;
  const sim = playground.simulation;
  // time sim update (4 substeps already inside playground.update -> but call sim.update directly x4 like the real loop)
  let tSim = 0, tRender = 0;
  for (let f=0; f<N; f++){
    let a = performance.now();
    playground.simulation.updateGlassTilt(1/60);
    for (let s=0;s<4;s++) playground.simulation.update(1/60*1.85);
    let b = performance.now();
    drawBackground(); playground.drawBack(); renderBeer(); renderFoam(); playground.drawFront();
    let c = performance.now();
    tSim += (b-a); tRender += (c-b);
  }
  return { particles: sim.particles.length, foam: sim.foamParticles.length,
           simMs: +(tSim/N).toFixed(2), renderMs: +(tRender/N).toFixed(2),
           totalMs: +((tSim+tRender)/N).toFixed(2) };
});
console.log(JSON.stringify(r));
await browser.close();

