neighbourSearch(){
    this.fluidHashGrid.clearGrid();
    this.fluidHashGrid.mapParticleToCell();
}

// Gather every particle's neighbours once into a flat list (CSR layout) so the
// viscosity and density-relaxation passes don't re-scan the grid 3x per step.
buildNeighbors(){
    let grid = this.fluidHashGrid;
    let cell = grid.cellSize;
    let map = grid.hashMap;
    let ps = this.particles;
    let n = ps.length;
    if(this.nbrStart.length < n + 1){
        this.nbrStart = new Int32Array(n + 1);
    }
    let idx = this.nbrIdx;
    idx.length = 0;
    for(let i=0; i<n; i++){
        this.nbrStart[i] = idx.length;
        let pos = ps[i].position;
        let gx = (pos.x / cell) | 0;
        let gy = (pos.y / cell) | 0;
        for(let dx=-1; dx<=1; dx++){
            for(let dy=-1; dy<=1; dy++){
                let content = map.get(grid.cellIndexToHash(gx + dx, gy + dy));
                if(content){
                    for(let m=0; m<content.length; m++){
                        let j = content[m];
                        if(j !== i){
                            idx.push(j);
                        }
                    }
                }
            }
        }
    }
    this.nbrStart[n] = idx.length;
}

