doubleDensityRelaxation(dt){
    for(let i=0; i< this.particles.length; i++){
        let density = 0;
        let densityNear = 0;
        let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
        let particleA = this.particles[i];

        for(let j = 0; j < neighbours.length;j++){
            let particleB = this.particles[neighbours[j]];
            if(particleA == particleB) continue;

            let rij = Sub(particleB.position,particleA.position);
            let q = rij.Length() / this.INTERACTION_RADIUS;

            if(q < 1){
                let oneMinusQ = (1-q);
                density += oneMinusQ*oneMinusQ;
                densityNear += oneMinusQ*oneMinusQ*oneMinusQ;
            }
        }

        let pressure = this.K * (density - this.REST_DENSITY);
        let pressureNear = this.K_NEAR * densityNear;
        let particleADisplacement = Vector2.Zero();

        for(let j=0; j< neighbours.length; j++){
            let particleB = this.particles[neighbours[j]];
            if(particleA == particleB){
                continue;
            }

            let rij = Sub(particleB.position, particleA.position);
            let distance = rij.Length();
            if(distance < 0.0001){
                rij = new Vector2(Math.random() - 0.5, Math.random() - 0.5);
                distance = rij.Length();
            }

            let q = distance / this.INTERACTION_RADIUS;

            if(q < 1.0){
                rij.Normalize();
                let displacementTerm = Math.pow(dt, 2) *
                    (pressure * (1-q) + pressureNear * Math.pow(1-q, 2));
                let D = Scale(rij, displacementTerm);

                particleB.position = Add(particleB.position, Scale(D,0.5));
                particleADisplacement = Sub(particleADisplacement, Scale(D,0.5));
            }
        }

        particleA.position = Add(particleA.position, particleADisplacement);
    }
}

input.new_string:
doubleDensityRelaxation(dt){
    let ps = this.particles;
    let nbr = this.nbrIdx;
    let start = this.nbrStart;
    let R = this.INTERACTION_RADIUS;
    let R2 = R * R;
    let invR = 1 / R;
    let dt2 = dt * dt;
    let K = this.K;
    let KNEAR = this.K_NEAR;
    let REST = this.REST_DENSITY;

    for(let i=0; i<ps.length; i++){
        let pa = ps[i];
        let pax = pa.position.x;
        let pay = pa.position.y;
        let s = start[i];
        let e = start[i+1];

        let density = 0;
        let densityNear = 0;
        for(let k=s; k<e; k++){
            let pb = ps[nbr[k]];
            let rx = pb.position.x - pax;
            let ry = pb.position.y - pay;
            let d2 = rx*rx + ry*ry;
            if(d2 < R2){
                let omq = 1 - Math.sqrt(d2) * invR;
                density += omq*omq;
                densityNear += omq*omq*omq;
            }
        }

        let pressure = K * (density - REST);
        let pressureNear = KNEAR * densityNear;
        let dax = 0;
        let day = 0;

        for(let k=s; k<e; k++){
            let pb = ps[nbr[k]];
            let rx = pb.position.x - pax;
            let ry = pb.position.y - pay;
            let d2 = rx*rx + ry*ry;
            if(d2 >= R2){
                continue;
            }
            let dist = Math.sqrt(d2);
            if(dist < 0.0001){
                rx = Math.random() - 0.5;
                ry = Math.random() - 0.5;
                dist = Math.sqrt(rx*rx + ry*ry);
            }
            let omq = 1 - dist * invR;
            let disp = dt2 * (pressure * omq + pressureNear * omq * omq);
            let f = 0.5 * disp / dist;
            let dx = rx * f;
            let dy = ry * f;
            pb.position.x += dx;
            pb.position.y += dy;
            dax -= dx;
            day -= dy;
        }

        pa.position.x += dax;
        pa.position.y += day;
    }
}

