var BEER_RADIUS = 11;
var FOAM_RADIUS = 12;

window.BEER_RADIUS = BEER_RADIUS;
window.FOAM_RADIUS = FOAM_RADIUS;

let lastTime = performance.now();
let currentTime = 0;
let deltaTime = 0;

let playground = new Playground();

mainLoop();

function updatePlayground(dt){
    playground.update(dt);

    drawBackground();
    playground.drawBack();
    renderBeer();
    renderFoam();
    playground.drawFront();
}

function drawBackground(){
    let bg = ctx.createLinearGradient(0, 0, 0, canvas.height);
    bg.addColorStop(0, "#f3ecdc");
    bg.addColorStop(0.55, "#ece2cd");
    bg.addColorStop(1, "#e2d6bd");
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // soft warm vignette from top-right (light source)
    let glow = ctx.createRadialGradient(canvas.width * 0.74, 120, 60, canvas.width * 0.74, 120, 720);
    glow.addColorStop(0, "rgba(255,248,225,0.55)");
    glow.addColorStop(1, "rgba(255,248,225,0)");
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // table contact shadow under the glass
    if(playground.simulation && playground.simulation.glass){
        let g = playground.simulation.glass;
        let cx = g.center.x;
        let cy = g.center.y + g.height * 0.5 + 14;
        let sh = ctx.createRadialGradient(cx, cy, 8, cx, cy, g.topWidth * 0.95);
        sh.addColorStop(0, "rgba(60,45,20,0.20)");
        sh.addColorStop(1, "rgba(60,45,20,0)");
        ctx.fillStyle = sh;
        ctx.save();
        ctx.translate(cx, cy);
        ctx.scale(1, 0.26);
        ctx.beginPath();
        ctx.arc(0, 0, g.topWidth * 0.92, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
    }
}

function renderBeer(){
    beerMaskCtx.clearRect(0, 0, beerMaskCanvas.width, beerMaskCanvas.height);
    playground.drawBeer(beerMaskCtx);

    beerCtx.clearRect(0, 0, beerCanvas.width, beerCanvas.height);
    beerCtx.save();
    beerCtx.filter = "url(#beerGoo)";
    beerCtx.drawImage(beerMaskCanvas, 0, 0);
    beerCtx.filter = "none";
    beerCtx.globalCompositeOperation = "source-in";

    let beerGradient = beerCtx.createLinearGradient(0, 150, 0, 660);
    beerGradient.addColorStop(0.0, "#ffd166");
    beerGradient.addColorStop(0.28, "#f9b53c");
    beerGradient.addColorStop(0.62, "#ef921b");
    beerGradient.addColorStop(1.0, "#d16f08");
    beerCtx.fillStyle = beerGradient;
    beerCtx.fillRect(0, 0, beerCanvas.width, beerCanvas.height);

    // left-to-right sheen so the stream/body looks glassy and lit from the right
    beerCtx.globalCompositeOperation = "source-atop";
    let sheen = beerCtx.createLinearGradient(0, 0, canvas.width, 0);
    sheen.addColorStop(0.0, "rgba(120,50,0,0.22)");
    sheen.addColorStop(0.45, "rgba(255,210,120,0.05)");
    sheen.addColorStop(0.85, "rgba(255,240,190,0.30)");
    sheen.addColorStop(1.0, "rgba(255,250,220,0.42)");
    beerCtx.fillStyle = sheen;
    beerCtx.fillRect(0, 0, beerCanvas.width, beerCanvas.height);
    beerCtx.restore();

    ctx.drawImage(beerCanvas, 0, 0);
    playground.drawBeerDetails(ctx);
}

function renderFoam(){
    foamMaskCtx.clearRect(0, 0, foamMaskCanvas.width, foamMaskCanvas.height);
    playground.drawFoam(foamMaskCtx);

    foamCtx.clearRect(0, 0, foamCanvas.width, foamCanvas.height);
    foamCtx.save();
    foamCtx.filter = "url(#foamGoo)";
    foamCtx.drawImage(foamMaskCanvas, 0, 0);
    foamCtx.filter = "none";
    foamCtx.globalCompositeOperation = "source-in";

    let foamGradient = foamCtx.createLinearGradient(0, 0, 0, foamCanvas.height);
    foamGradient.addColorStop(0.0, "#fffefa");
    foamGradient.addColorStop(0.5, "#fdf3da");
    foamGradient.addColorStop(0.85, "#f0dcae");
    foamGradient.addColorStop(1.0, "#e0c084");
    foamCtx.fillStyle = foamGradient;
    foamCtx.fillRect(0, 0, foamCanvas.width, foamCanvas.height);
    foamCtx.restore();

    ctx.drawImage(foamCanvas, 0, 0);
    playground.drawFoamDetails(ctx);
}

function mainLoop(){
    window.requestAnimationFrame(mainLoop);

    currentTime = performance.now();
    deltaTime = (currentTime - lastTime) / 1000;

    updatePlayground(deltaTime);
    lastTime = currentTime;
}

function getMousePos(canvas, evt){
    var rect = canvas.getBoundingClientRect();
    return {
        x: (evt.clientX - rect.left) * (canvas.width / rect.width),
        y: (evt.clientY - rect.top) * (canvas.height / rect.height)
    };
}

